import type { ItemDef, UnitKey } from '../lib/quiz'

// Preguntas generadas con IA dentro de «Simulacro DSI (preguntas viejas y nuevas).html». No son de la cátedra.
export const practicaSimulacroIa: (ItemDef & { unit: UnitKey; id: string })[] = [
  {"id": "ia-01-05", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-05 · pregunta generada con IA", "q": "Según las señales que presentan las clases teóricas para detectar que una clase incumple el Principio de Responsabilidad Única, ¿cuáles de los siguientes son indicios de incumplimiento? Seleccione todas las correctas.", "o": ["La clase implementa una interfaz pequeña y cohesiva.", "En la misma clase están involucradas dos capas de la arquitectura, por ejemplo lógica de negocio y persistencia.", "Tiene un número elevado de métodos públicos y resulta difícil escribirle pruebas unitarias.", "La clase depende de una abstracción en lugar de una clase concreta.", "Un grupo de métodos usa la mitad de los atributos y otro grupo usa la otra mitad."], "a": [1, 2, 4], "e": "«La clase implementa una interfaz pequeña y cohesiva.»: es lo que recomienda ISP. No indica un problema de SRP.\n«En la misma clase están involucradas dos capas de la…»: mezclar capas implica más de una razón de cambio.\n«Tiene un número elevado de métodos públicos y resulta…»: ambas son señales que listan las clases teóricas.\n«La clase depende de una abstracción en lugar de una clase…»: es lo que recomienda DIP.\n«Un grupo de métodos usa la mitad de los atributos y otro…»: muestra que la clase podría dividirse en dos.", "inf": true, "ref": "Powers de Clase (SOLID); apunte, pág. 6."},
  {"id": "ia-01-06", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-06 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre el Principio Abierto/Cerrado.", "o": ["Se cumple siempre que la clase tenga pocas líneas de código, sin importar cómo se agreguen las variantes.", "Ayuda a no tener que volver a testear una clase que ya funciona correctamente.", "Prohíbe usar herencia, porque la extensión solo puede hacerse por composición.", "Una cadena de if/else o switch que evalúa \"tipos\" y debe tocarse con cada variante nueva es una señal de incumplimiento.", "Propone cambiar el comportamiento de una clase mediante herencia, polimorfismo y composición, preparando el código para los cambios previsibles."], "a": [1, 3, 4], "e": "«Se cumple siempre que la clase tenga pocas líneas de…»: el tamaño de la clase no determina si cumple OCP.\n«Ayuda a no tener que volver a testear una clase que ya…»: lo señalan las clases teóricas: si no se modifica lo existente, no hace falta retestearlo.\n«Prohíbe usar herencia, porque la extensión solo puede…»: el apunte menciona explícitamente la herencia como mecanismo válido.\n«Una cadena de if/else o switch que evalúa \"tipos\" y debe…»: es la señal clásica. Carmona la ilustra con un EditorGrafico que evalúa el tipo de forma.\n«Propone cambiar el comportamiento de una clase mediante…»: es la interpretación que da el apunte: anticiparse al cambio.", "inf": true, "ref": "apunte, pág. 7; Carmona; Powers de Clase."},
  {"id": "ia-01-07", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-07 · pregunta generada con IA", "q": "Analice el siguiente código. El cliente espera obtener un área de 6, pero obtiene 9. ¿Cuáles de las siguientes afirmaciones son correctas? Seleccione todas las correctas.", "code": "class Rectangulo {\n    protected int alto, ancho;\n    void setAlto(int a)  { alto = a; }\n    void setAncho(int a) { ancho = a; }\n    int area() { return alto * ancho; }\n}\n\nclass Cuadrado extends Rectangulo {\n    @Override void setAlto(int a)  { alto = a; ancho = a; }\n    @Override void setAncho(int a) { alto = a; ancho = a; }\n}\n\n// Cliente\nRectangulo r = new Cuadrado();\nr.setAlto(2);\nr.setAncho(3);\nint area = r.area();", "o": ["El diseño es correcto: como matemáticamente un cuadrado es un rectángulo, eso alcanza para usar herencia.", "La solución adecuada es agregar en el cliente un chequeo instanceof para tratar aparte a los cuadrados.", "Una solución posible es eliminar esa herencia y definir una abstracción común, como una interfaz IRectangular.", "Incumple LSP, porque el cliente que usa una referencia a Rectangulo obtiene un resultado distinto del que espera de la clase base.", "Incumple principalmente ISP, porque Rectangulo expone demasiados métodos."], "a": [2, 3], "e": "«El diseño es correcto: como matemáticamente un cuadrado es…»: la relación matemática no garantiza que el subtipo sea sustituible.\n«La solución adecuada es agregar en el cliente un chequeo…»: instanceof en el cliente es un síntoma de incumplimiento de LSP, no una solución.\n«Una solución posible es eliminar esa herencia y definir una…»: es la solución que muestran Carmona y Duarte.\n«Incumple LSP, porque el cliente que usa una referencia a…»: las funciones que usan referencias a la clase base deben poder usar las derivadas sin saberlo.\n«Incumple principalmente ISP, porque Rectangulo expone…»: la interfaz no obliga a nadie a implementar algo que no usa.", "inf": true, "ref": "apunte, pág. 7; Carmona; Tomás Duarte."},
  {"id": "ia-01-08", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-08 · pregunta generada con IA", "q": "Una subclase sobrescribe métodos de su clase base. ¿Cuáles de las siguientes situaciones indican que probablemente se incumple el Principio de Sustitución de Liskov? Seleccione todas las correctas.", "o": ["La subclase agrega un método nuevo sin alterar el comportamiento de los heredados.", "La subclase refuerza las precondiciones o debilita las postcondiciones del método.", "Los clientes usan objetos de la subclase a través de una referencia a la clase base sin saberlo.", "Los tests escritos para la clase padre fallan al ejecutarse sobre la clase hija.", "El método sobrescrito queda vacío o lanza NotImplementedException."], "a": [1, 3, 4], "e": "«La subclase agrega un método nuevo sin alterar el…»: agregar comportamiento no rompe el contrato de la clase base.\n«La subclase refuerza las precondiciones o debilita las…»: según Pressman y Maxim, rompe el contrato implícito entre la clase base y el cliente.\n«Los clientes usan objetos de la subclase a través de una…»: es exactamente lo que LSP pide.\n«Los tests escritos para la clase padre fallan al ejecutarse…»: es otra de las señales de las clases teóricas.\n«El método sobrescrito queda vacío o lanza…»: lo señalan las clases teóricas: \"donde se espera el padre debe funcionar de igual manera si se utiliza al hijo\".", "inf": true, "ref": "Powers de Clase; Pressman y Maxim; apunte, pág. 7."},
  {"id": "ia-01-09", "unit": "b1", "t": "mc", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-09 · pregunta generada con IA", "q": "Analice el siguiente código y responda: ¿qué principio SOLID incumple principalmente este diseño?", "code": "interface ITrabajador {\n    void trabajar();\n    void descansar();\n    void comer();\n}\n\nclass Robot implements ITrabajador {\n    public void trabajar() { /* ... */ }\n    public void descansar() { throw new UnsupportedOperationException(); }\n    public void comer()     { throw new UnsupportedOperationException(\"No como\"); }\n}", "o": ["Abierto/Cerrado (Open/Closed Principle)", "Responsabilidad Única (Single Responsibility Principle)", "Inversión de Dependencias (Dependency Inversion Principle)", "Segregación de Interfaces (Interface Segregation Principle)", "Substitución de Liskov (Liskov Substitution Principle)"], "a": 3, "e": "«Abierto/Cerrado (Open/Closed Principle)» / «Responsabilidad Única (Single Responsibility Principle)» / «Inversión de Dependencias (Dependency Inversion Principle)»: no describen el problema principal de este código.\n«Segregación de Interfaces (Interface Segregation Principle)»: ITrabajador es una interfaz \"gorda\" que obliga a Robot a implementar métodos que no usa. La solución es segregarla en ITrabajar, IDescansar e IComer.\n«Substitución de Liskov (Liskov Substitution Principle)»: lanzar excepciones también es un síntoma de LSP, pero la causa de fondo es la interfaz demasiado grande.", "inf": true, "ref": "apunte, pág. 7; Carmona; Tomás Duarte."},
  {"id": "ia-01-10", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-10 · pregunta generada con IA", "q": "Analice el siguiente código. ¿Cuáles de las siguientes afirmaciones son correctas? Seleccione todas las correctas.", "code": "public class House {\n    private Door _door;\n    private Window _window;\n\n    public House() {\n        _door = new Door();\n        _window = new Window();\n    }\n}", "o": ["Este acoplamiento dificulta hacer pruebas unitarias aisladas con objetos simulados (mocking).", "Incumple el Principio de Inversión de Dependencias, porque House depende directamente de clases concretas.", "El principio exige eliminar toda relación entre House y sus colaboradores.", "Una solución es definir IDoor e IWindow e inyectarlas por el constructor de House.", "Se corrige haciendo que Door y Window hereden de House."], "a": [0, 1, 3], "e": "«Este acoplamiento dificulta hacer pruebas unitarias…»: el apunte vincula los principios SOLID con la facilidad para usar mocks.\n«Incumple el Principio de Inversión de Dependencias, porque…»: módulos de alto nivel y de bajo nivel deberían depender de abstracciones.\n«El principio exige eliminar toda relación entre House y sus…»: DIP no elimina la relación: la hace pasar por una abstracción.\n«Una solución es definir IDoor e IWindow e inyectarlas por…»: es la solución que muestran Carmona y Duarte.\n«Se corrige haciendo que Door y Window hereden de House.»: una puerta no es una casa, y la herencia no invierte la dependencia.", "inf": true, "ref": "apunte, págs. 5 y 8; Carmona; Tomás Duarte."},
  {"id": "ia-01-11", "unit": "b1", "t": "multi", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-11 · pregunta generada con IA", "q": "Según el apunte, ¿qué afirmaciones sobre la relación entre los principios SOLID son correctas? Seleccione todas las correctas.", "o": ["Al aplicar un principio se puede estar dando la espalda a otro.", "Un mismo problema puede resolverse desde la perspectiva de distintos principios, con el mismo resultado.", "Un diseño de calidad debe cumplir siempre los cinco principios a la vez, sin excepción.", "Si una clase A cambia inevitablemente cada vez que cambia B, posiblemente incumpla SRP, y el problema puede resolverse aplicando DIP.", "Cada principio es independiente: aplicarlo no tiene efecto sobre los demás."], "a": [0, 1, 3], "e": "«Al aplicar un principio se puede estar dando la espalda a…»: es la segunda consecuencia que señala el apunte.\n«Un mismo problema puede resolverse desde la perspectiva de…»: lo dice el apunte a partir del mismo ejemplo.\n«Un diseño de calidad debe cumplir siempre los cinco…»: el apunte aclara que muchas veces es imposible cumplir todos a la vez.\n«Si una clase A cambia inevitablemente cada vez que cambia…»: es el ejemplo del apunte.\n«Cada principio es independiente: aplicarlo no tiene efecto…»: el apunte dice lo contrario: \"actúan como un todo\".", "inf": true, "ref": "apunte, págs. 5-6."},
  {"id": "ia-01-12", "unit": "b1", "t": "rel", "tema": "SOLID", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 01-12 · pregunta generada con IA", "q": "Empareje cada principio SOLID con el síntoma que indica su incumplimiento.", "i": [["SRP", "Una clase Factura tiene calcularTotal(), generarPDF() y enviarPorEmail()."], ["OCP", "Cada sensor nuevo obliga a agregar otra rama if/else en la clase Detector."], ["LSP", "Los tests de la clase padre fallan al ejecutarse sobre la clase hija."], ["ISP", "Robot debe implementar comer() porque está en la interfaz que usa."], ["DIP", "UserController crea su servicio de correo con new ServicioEmail()."]], "e": "Los ejemplos salen de las fuentes: Factura (apunte teórico en NotebookLM), Detector (Pressman y Maxim, sistema SafeHome), tests del padre (Powers de Clase), Robot y UserController (Carmona, Tomás Duarte).", "inf": true, "ref": "apunte, págs. 6-8."},
  {"id": "ia-02-05", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-05 · pregunta generada con IA", "q": "En un sistema de punto de venta, una Sale (venta) agrega de forma compositiva varias instancias de SalesLineItem (línea de venta). Según el patrón Creador, ¿qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Register debe crear las líneas de venta, porque es la clase que recibe los eventos del sistema.", "Elegir a Sale como creadora favorece el bajo acoplamiento, porque ya debe estar conectada con SalesLineItem.", "Conviene crear una clase LineItemFactory en todos los casos, porque la creación nunca debe quedar en una clase del dominio.", "Sale es una buena candidata a crear SalesLineItem, porque la contiene o agrega."], "a": [1, 3], "e": "«Register debe crear las líneas de venta, porque es la clase…»: esa lógica confunde Controlador con Creador.\n«Elegir a Sale como creadora favorece el bajo acoplamiento,…»: la intención del patrón es encontrar un creador que de todos modos deba estar conectado al objeto creado.\n«Conviene crear una clase LineItemFactory en todos los…»: una fábrica se justifica cuando la creación es compleja, no siempre.\n«Sale es una buena candidata a crear SalesLineItem, porque…»: \"B contiene o agrega compositivamente a A\" es la primera condición.", "inf": true, "ref": "apunte, pág. 9; Larman, cap. 17."},
  {"id": "ia-02-06", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-06 · pregunta generada con IA", "q": "¿En cuáles de las siguientes situaciones es aconsejable delegar la creación a una fábrica (Concrete Factory o Abstract Factory) en lugar de usar la clase sugerida por Creador? Seleccione todas las correctas.", "o": ["Cuando la clase creadora y la creada ya están asociadas en el modelo.", "Cuando hay que crear condicionalmente una instancia de una familia de clases similares según el valor de una propiedad externa.", "Cuando hay que reutilizar instancias recicladas por motivos de rendimiento.", "Cuando la clase creadora contiene a la creada y tiene sus datos de inicialización."], "a": [1, 2], "e": "«Cuando la clase creadora y la creada ya están asociadas en…» / «Cuando la clase creadora contiene a la creada y tiene sus…»: son los casos en que Creador funciona bien.\n«Cuando hay que crear condicionalmente una instancia de una…»: es la otra contraindicación del apunte.\n«Cuando hay que reutilizar instancias recicladas por motivos…»: es una de las contraindicaciones que da el apunte.", "inf": true, "ref": "apunte, pág. 9."},
  {"id": "ia-02-07", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-07 · pregunta generada con IA", "q": "Se debe calcular el total de una venta. Sale conoce sus líneas, SalesLineItem conoce la cantidad y su descripción de producto, y ProductDescription conoce el precio. Según Experto en Información, ¿qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Register debe calcular el total porque coordina la operación del sistema.", "La información está repartida, por lo que varios expertos parciales colaboran en la tarea.", "Sale debe responder getTotal() recorriendo sus líneas.", "SalesLineItem debe calcular su subtotal a partir de la cantidad y del precio que le da la descripción.", "Toda la información debe centralizarse en una sola clase para que haya un único experto."], "a": [1, 2, 3], "e": "«Register debe calcular el total porque coordina la…»: el controlador coordina y delega; no hace el trabajo.\n«La información está repartida, por lo que varios expertos…»: es lo que el apunte llama \"expertos de información parciales\".\n«Sale debe responder getTotal() recorriendo sus líneas.»: sale es la experta en la suma global.\n«SalesLineItem debe calcular su subtotal a partir de la…»: salesLineItem es la experta en el subtotal, y ProductDescription en el precio.\n«Toda la información debe centralizarse en una sola clase…»: contradice la idea de expertos parciales y empeora la cohesión.", "inf": true, "ref": "apunte, pág. 10; Larman, cap. 17."},
  {"id": "ia-02-08", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-08 · pregunta generada con IA", "q": "Un diseñador propone que la clase Sale se guarde a sí misma en la base de datos, argumentando que tiene casi toda la información necesaria. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Es una contraindicación de Experto: Sale perdería cohesión al mezclar lógica de dominio y de persistencia.", "El problema se resuelve haciendo que Sale herede de una clase que represente la base de datos, sin más cambios.", "Una alternativa es crear una clase como PersistentStorage, aplicando Fabricación Pura.", "Es la mejor solución, porque Experto siempre tiene prioridad sobre los demás patrones.", "Sale quedaría acoplada al motor de base de datos, y el código de guardado podría duplicarse en cada clase."], "a": [0, 2, 4], "e": "«Es una contraindicación de Experto: Sale perdería cohesión…»: el apunte dice que conviene evitar Experto cuando mezcla responsabilidades muy diferentes.\n«El problema se resuelve haciendo que Sale herede de una…»: la herencia mantiene a Sale ligada a la persistencia (explicación propia).\n«Una alternativa es crear una clase como PersistentStorage,…»: es la solución de Larman.\n«Es la mejor solución, porque Experto siempre tiene…»: en estos casos hay que priorizar bajo acoplamiento y alta cohesión.\n«Sale quedaría acoplada al motor de base de datos, y el…»: son los problemas que enumera el apunte.", "inf": true, "ref": "apunte, págs. 10-11; Larman, cap. 25."},
  {"id": "ia-02-09", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-09 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre el patrón Bajo Acoplamiento.", "o": ["Conviene especialmente en clases genéricas con alta probabilidad de reutilización.", "El alto acoplamiento a elementos estables y pervasivos rara vez es un problema.", "Existe una medida absoluta que indica cuándo el acoplamiento es demasiado alto.", "Es un principio evaluativo que se considera en todas las decisiones de diseño.", "El diseño ideal es que no exista acoplamiento entre clases."], "a": [0, 1, 3], "e": "«Conviene especialmente en clases genéricas con alta…»: lo dice el apunte de forma explícita.\n«El alto acoplamiento a elementos estables y pervasivos rara…»: el problema es el acoplamiento a elementos inestables.\n«Existe una medida absoluta que indica cuándo el…»: el apunte aclara que no hay medida absoluta.\n«Es un principio evaluativo que se considera en todas las…»: es \"una meta subyacente que se debe considerar continuamente\".\n«El diseño ideal es que no exista acoplamiento entre clases.»: el caso extremo ofende la metáfora de objetos que colaboran; llevado al exceso produce un mal diseño.", "inf": true, "ref": "apunte, págs. 12-13."},
  {"id": "ia-02-10", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-10 · pregunta generada con IA", "q": "Un cajero presiona el botón \"End Sale\" en una terminal. Según el patrón Controlador, ¿qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["El controlador normalmente no hace el trabajo, sino que lo delega a otros objetos.", "Un controlador puede representar el sistema en general o un escenario de caso de uso.", "El controlador debe hacer él mismo los cálculos de negocio para evitar llamar a otros objetos.", "El evento debe ser manejado por el primer objeto más allá de la capa de interfaz de usuario.", "La ventana donde está el botón debe contener la lógica que cierra la venta."], "a": [0, 1, 3], "e": "«El controlador normalmente no hace el trabajo, sino que lo…»: es un patrón de delegación.\n«Un controlador puede representar el sistema en general o un…»: son las dos opciones de asignación.\n«El controlador debe hacer él mismo los cálculos de negocio…»: es una señal de controlador inflado.\n«El evento debe ser manejado por el primer objeto más allá…»: es la definición que da el apunte.\n«La ventana donde está el botón debe contener la lógica que…»: la capa de UI no debe contener lógica de aplicación.", "inf": true, "ref": "apunte, págs. 13-14."},
  {"id": "ia-02-11", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-11 · pregunta generada con IA", "q": "Un sistema tiene una única clase POSSystem que recibe todos los eventos del sistema, que son muchos. Además, esa clase calcula importes y accede a la base de datos. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Es un controlador inflado, un defecto común que conduce a baja cohesión.", "La clase debería delegar el trabajo a los objetos de dominio correspondientes.", "El facade controller es siempre preferible, sin importar la cantidad de eventos del sistema.", "Una alternativa es usar controladores de caso de uso, como ProcessSaleHandler.", "Un controlador de caso de uso es un objeto de dominio que aparece en el modelo conceptual."], "a": [0, 1, 3], "e": "«Es un controlador inflado, un defecto común que conduce a…»: un único controlador con muchos eventos, y que además hace el trabajo, es la señal típica.\n«La clase debería delegar el trabajo a los objetos de…»: es la consecuencia de aplicar Experto y Alta Cohesión.\n«El facade controller es siempre preferible, sin importar la…»: es útil cuando no hay demasiados eventos del sistema.\n«Una alternativa es usar controladores de caso de uso, como…»: se usa cuando el facade controller se vuelve \"inflado\".\n«Un controlador de caso de uso es un objeto de dominio que…»: el apunte aclara que no es un objeto de dominio, sino una fabricación pura.", "inf": true, "ref": "apunte, pág. 14; Larman, cap. 17."},
  {"id": "ia-02-12", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-12 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre el patrón Alta Cohesión.", "o": ["Por desempeño, a veces conviene hacer objetos remotos más grandes y menos cohesivos para reducir las llamadas remotas.", "Nunca está justificado aceptar menor cohesión.", "Una clase con alta cohesión tiene relativamente pocos métodos, con funcionalidad muy relacionada, y colabora con otros objetos si la tarea es grande.", "Mala cohesión usualmente genera mal acoplamiento, y viceversa.", "Una clase cohesiva debe hacer todo el trabajo por sí misma, sin colaborar con otras."], "a": [0, 2, 3], "e": "«Por desempeño, a veces conviene hacer objetos remotos más…»: es el patrón Coarse-Grained Remote Interface.\n«Nunca está justificado aceptar menor cohesión.»: el apunte da dos contraindicaciones: mantenimiento especializado y objetos remotos.\n«Una clase con alta cohesión tiene relativamente pocos…»: es la regla práctica del apunte.\n«Mala cohesión usualmente genera mal acoplamiento, y…»: cohesión y acoplamiento son \"yin y yang\".\n«Una clase cohesiva debe hacer todo el trabajo por sí misma,…»: contradice la regla práctica.", "inf": true, "ref": "apunte, págs. 15-16."},
  {"id": "ia-02-13", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-13 · pregunta generada con IA", "q": "El sistema debe consultar distintos calculadores de impuestos externos. Hoy la clase Sale contiene un switch según el tipo de calculador. Se propone definir ITaxCalculatorAdapter con implementaciones como TaxMasterAdapter y GoodAsGoldTaxProAdapter. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Es un caso de Creador, porque Sale crea los calculadores.", "Los adaptadores actúan como objetos intermedios entre Sale y los sistemas externos, por lo que también hay Indirección.", "La interfaz protege al sistema de la variación en los calculadores, por lo que también hay Variaciones Protegidas.", "Polimorfismo recomienda crear jerarquías para toda variación futura imaginable, aunque hoy no exista.", "Aplica Polimorfismo: la responsabilidad se asigna a los tipos para los cuales el comportamiento varía."], "a": [1, 2, 4], "e": "«Es un caso de Creador, porque Sale crea los calculadores.»: el enunciado no habla de quién crea los calculadores.\n«Los adaptadores actúan como objetos intermedios entre Sale…»: es el ejemplo de Larman para Indirección.\n«La interfaz protege al sistema de la variación en los…»: los tres patrones suelen aparecer juntos.\n«Polimorfismo recomienda crear jerarquías para toda…»: larman advierte contra diseñar para futuros hipotéticos.\n«Aplica Polimorfismo: la responsabilidad se asigna a los…»: evita los condicionales por tipo.", "inf": true, "ref": "apunte, págs. 16-17; Larman, cap. 25."},
  {"id": "ia-02-14", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-14 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre Fabricación Pura son correctas? Seleccione todas las correctas.", "o": ["Debe evitarse siempre que la información esté repartida entre varias clases.", "Se crea intencionadamente para disminuir el acoplamiento, aumentar la cohesión o potenciar la reutilización.", "Su uso abusivo puede generar clases función o algoritmo, con un solo método, y una descomposición de estilo procedimental.", "La clase creada debe representar un concepto importante del dominio del problema."], "a": [1, 2], "e": "«Debe evitarse siempre que la información esté repartida…»: la información repartida se resuelve con expertos parciales; no tiene relación con esta restricción.\n«Se crea intencionadamente para disminuir el acoplamiento,…»: es la definición del apunte.\n«Su uso abusivo puede generar clases función o algoritmo,…»: es la contraindicación del apunte. Larman la llama descomposición conductual.\n«La clase creada debe representar un concepto importante del…»: es lo contrario: no representa un objeto real del dominio.", "inf": true, "ref": "apunte, págs. 16-17; Larman, cap. 25."},
  {"id": "ia-02-15", "unit": "b1", "t": "multi", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-15 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre Indirección y Variaciones Protegidas.", "o": ["Indirección asigna la mediación entre dos elementos a un objeto intermedio.", "Un punto de evolución es una variación presente en los requisitos actuales.", "Larman recomienda proteger todos los puntos de evolución imaginables, porque siempre es más barato que modificar después.", "Variaciones Protegidas consiste en identificar puntos de variación previstos y crear una interfaz estable a su alrededor.", "Según Larman, Variaciones Protegidas es esencialmente equivalente al ocultamiento de información de Parnas y al principio abierto/cerrado."], "a": [0, 3, 4], "e": "«Indirección asigna la mediación entre dos elementos a un…»: es la solución del patrón.\n«Un punto de evolución es una variación presente en los…»: eso es un punto de variación. El de evolución es especulativo.\n«Larman recomienda proteger todos los puntos de evolución…»: larman advierte lo contrario: hay que elegir las batallas.\n«Variaciones Protegidas consiste en identificar puntos de…»: es la definición del patrón.\n«Según Larman, Variaciones Protegidas es esencialmente…»: difieren solo en el énfasis.", "inf": true, "ref": "apunte, pág. 17; Larman, cap. 25."},
  {"id": "ia-02-16", "unit": "b1", "t": "rel", "tema": "GRASP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 02-16 · pregunta generada con IA", "q": "Empareje cada patrón GRASP con la pregunta que responde.", "i": [["Creador", "¿Quién debería ser responsable de crear una nueva instancia de una clase?"], ["Experto en Información", "¿Cuál es un principio general para asignar responsabilidades a los objetos?"], ["Bajo Acoplamiento", "¿Cómo apoyar baja dependencia, bajo impacto de cambios y mayor reutilización?"], ["Controlador", "¿Qué primer objeto más allá de la capa de UI recibe y coordina una operación del sistema?"], ["Alta Cohesión", "¿Cómo mantener los objetos enfocados, comprensibles y manejables?"], ["Polimorfismo", "¿Cómo manejar alternativas de comportamiento basadas en el tipo, sin condicionales?"], ["Fabricación Pura", "¿Qué objeto asume la responsabilidad si Experto viola la cohesión o el acoplamiento?"], ["Indirección", "¿Dónde asignar una responsabilidad para evitar el acoplamiento directo entre elementos?"], ["Variaciones Protegidas", "¿Cómo diseñar para que los cambios en un elemento no impacten de forma indeseada en otros?"]], "e": "Cada patrón de Larman se presenta como un par problema-solución. Estas son las preguntas que encabezan cada uno.", "inf": true, "ref": "apunte, págs. 9-17; Larman, caps. 17 y 25."},
  {"id": "ia-03-05", "unit": "b2", "t": "multi", "tema": "Qué es arquitectura", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-05 · pregunta generada con IA", "q": "Según Bass et al., ¿cuáles de las siguientes afirmaciones sobre la arquitectura de software son correctas? Seleccione todas las correctas.", "o": ["Existe una única estructura que es \"la arquitectura\" del sistema.", "La arquitectura es diseño, pero no todo diseño es arquitectura.", "Todo sistema de software tiene una arquitectura, aunque no esté documentada.", "El comportamiento de los elementos nunca forma parte de la arquitectura.", "Se ocupa del lado público de las interfaces; los detalles privados de implementación no son arquitectónicos."], "a": [1, 2, 4], "e": "«Existe una única estructura que es \"la arquitectura\" del…»: el sistema tiene muchas estructuras y ninguna por sí sola es la arquitectura.\n«La arquitectura es diseño, pero no todo diseño es…»: es la relación que plantea el apunte.\n«Todo sistema de software tiene una arquitectura, aunque no…»: \"Una arquitectura puede existir independientemente de su descripción o especificación\".\n«El comportamiento de los elementos nunca forma parte de la…»: forma parte en la medida en que ayude a razonar sobre el sistema.\n«Se ocupa del lado público de las interfaces; los detalles…»: por eso la arquitectura es una abstracción.", "inf": true, "ref": "apunte, págs. 18-19; Bass et al."},
  {"id": "ia-03-06", "unit": "b2", "t": "rel", "tema": "Qué es arquitectura", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-06 · pregunta generada con IA", "q": "Empareje cada disciplina con la descripción que le corresponde.", "i": [["Arquitectura de software", "Determina cómo se estructura la funcionalidad y cómo interactúan los programas que residen en distintos procesadores."], ["Arquitectura de sistema", "Mapea funcionalidades a hardware y software, y permite razonar sobre consumo de energía, peso y dimensiones físicas."], ["Arquitectura empresarial", "Describe los procesos de la organización, el flujo de información, el personal y las subunidades organizacionales."]], "e": "La arquitectura de sistema se ocupa del conjunto total de hardware, software y humanos. En la empresarial, el software es solo una de las preocupaciones. Ambas proveen entornos y restricciones para la arquitectura de software.", "inf": true, "ref": "apunte, págs. 19-20."},
  {"id": "ia-03-07", "unit": "b2", "t": "mc", "tema": "Estructuras (Bass)", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-07 · pregunta generada con IA", "q": "Un arquitecto debe analizar tres preocupaciones: (1) cuánto impacta en el código cambiar una regla de negocio, (2) cuál es el tiempo de respuesta cuando varios clientes consultan al servidor, y (3) qué equipo de trabajo se hará cargo de cada parte. ¿Qué tipo de estructura es el más adecuado para cada una, en ese orden?", "o": ["Módulos, asignación, componentes y conectores.", "Asignación, módulos, componentes y conectores.", "Módulos, componentes y conectores, asignación.", "Componentes y conectores, asignación, módulos."], "a": 2, "e": "«Módulos, asignación, componentes y conectores.» / «Asignación, módulos, componentes y conectores.» / «Componentes y conectores, asignación, módulos.»: asignan las preocupaciones a estructuras que no permiten razonar sobre ellas.\n«Módulos, componentes y conectores, asignación.»: las estructuras de módulos son las herramientas principales para analizar la modificabilidad. Las de C&C sirven para las propiedades en tiempo de ejecución, como el rendimiento. Las de asignación relacionan el software con su organización.", "inf": true, "ref": "apunte, págs. 20-22."},
  {"id": "ia-03-08", "unit": "b2", "t": "rel", "tema": "Estructuras (Bass)", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-08 · pregunta generada con IA", "q": "Empareje cada estructura de asignación con lo que relaciona.", "i": [["Despliegue", "Software en ejecución con hardware o hardware virtualizado."], ["Implementación", "Módulos con estructuras de los entornos de desarrollo, integración, prueba o configuración."], ["Trabajo", "Software con equipos de trabajo."]], "e": "Las estructuras de asignación mapean las estructuras de software (C&C y módulos) con estructuras no relacionadas con el software, como su organización o sus entornos.", "inf": true, "ref": "apunte, págs. 21-22."},
  {"id": "ia-03-09", "unit": "b2", "t": "multi", "tema": "Qué es arquitectura", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-09 · pregunta generada con IA", "q": "Un equipo decide cifrar todo el tráfico entre componentes y dividir el sistema en muchos módulos muy desacoplados. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Los atributos de calidad dependen solo de la implementación final, no de la arquitectura.", "Cifrar el tráfico favorece la seguridad, pero puede hacer más lento el sistema.", "Desacoplar mucho facilita el mantenimiento, pero puede introducir sobrecarga y bajar el rendimiento.", "Una arquitectura adecuada permite maximizar todos los atributos de calidad a la vez.", "Al priorizar algunos atributos, la arquitectura puede inhibir otros."], "a": [1, 2, 4], "e": "«Los atributos de calidad dependen solo de la implementación…»: la arquitectura es el factor principal que determina si se cumplen.\n«Cifrar el tráfico favorece la seguridad, pero puede hacer…»: es el compromiso rendimiento vs. seguridad del apunte.\n«Desacoplar mucho facilita el mantenimiento, pero puede…»: es el compromiso modificabilidad vs. rendimiento.\n«Una arquitectura adecuada permite maximizar todos los…»: contradice la idea de compromisos: los atributos no se logran de forma aislada.\n«Al priorizar algunos atributos, la arquitectura puede…»: \"Una arquitectura puede inhibir o habilitar atributos de calidad\".", "inf": true, "ref": "apunte, págs. 22-23 y 25."},
  {"id": "ia-03-10", "unit": "b2", "t": "rel", "tema": "Modificabilidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-10 · pregunta generada con IA", "q": "Empareje cada cambio con su tipo, según cómo la arquitectura permite gestionarlo.", "i": [["Cambio local", "Modificar una regla de negocio en un solo servicio."], ["Cambio no local", "Agregar una regla nueva que además toca la base de datos y la interfaz, sin romper la base del sistema."], ["Cambio arquitectónico", "Pasar el sistema de un solo hilo a múltiples hilos."]], "e": "La arquitectura determina qué tan caro o fácil es adaptarse. El cambio arquitectónico afecta a todo el sistema.", "inf": true, "ref": "apunte, pág. 23."},
  {"id": "ia-03-11", "unit": "b2", "t": "multi", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-11 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre los atributos de calidad.", "o": ["Pueden lograrse de forma aislada, sin afectar a los demás atributos.", "Se relacionan con las funciones del sistema: un mismo requisito funcional puede tener anotaciones de rendimiento o de disponibilidad.", "Disponibilidad, rendimiento y usabilidad son observables mientras el sistema está en operación.", "Modificabilidad, testabilidad y desplegabilidad son observables únicamente por el usuario final en tiempo de ejecución.", "Son propiedades medibles o comprobables que reflejan qué tan bien el sistema satisface a los stakeholders, más allá de la funcionalidad básica."], "a": [1, 2, 4], "e": "«Pueden lograrse de forma aislada, sin afectar a los demás…»: \"nunca pueden lograrse de forma aislada\".\n«Se relacionan con las funciones del sistema: un mismo…»: es el ejemplo del botón verde del apunte.\n«Disponibilidad, rendimiento y usabilidad son observables…»: son atributos en tiempo de ejecución.\n«Modificabilidad, testabilidad y desplegabilidad son…»: esos son atributos de desarrollo, que afectan la construcción, la evolución y el mantenimiento.\n«Son propiedades medibles o comprobables que reflejan qué…»: es la definición del apunte.", "inf": true, "ref": "apunte, págs. 24-25."},
  {"id": "ia-03-12", "unit": "b2", "t": "multi", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-12 · pregunta generada con IA", "q": "Según el apunte, ¿qué afirmaciones sobre la disponibilidad (availability) son correctas? Seleccione todas las correctas.", "o": ["Los faults solo pueden corregirse después de que ocurren.", "Los estados intermedios entre un fault y una falla observable se llaman errores.", "Un fault es la falla observable por el usuario, y su causa se llama error.", "Se basa en la confiabilidad y le agrega la noción de recuperación: cuando el sistema falla, se repara."], "a": [1, 3], "e": "«Los faults solo pueden corregirse después de que ocurren.»: los faults pueden prevenirse, tolerarse, eliminarse o predecirse.\n«Los estados intermedios entre un fault y una falla…»: es la definición del apunte.\n«Un fault es la falla observable por el usuario, y su causa…»: invierte los términos: el fault es la causa interna.\n«Se basa en la confiabilidad y le agrega la noción de…»: es la definición del apunte.", "inf": true, "ref": "apunte, pág. 25."},
  {"id": "ia-03-13", "unit": "b2", "t": "rel", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-13 · pregunta generada con IA", "q": "Lea el siguiente escenario: \"Un desarrollador quiere cambiar la interfaz de usuario. El cambio se realiza en tiempo de diseño. Se modifica el código y se prueba el cambio. Tardará menos de tres horas y no habrá efectos secundarios.\" Empareje cada parte del escenario con su contenido.", "i": [["Fuente del estímulo", "Un desarrollador"], ["Estímulo", "Quiere hacer un cambio"], ["Artefacto", "La interfaz de usuario"], ["Entorno", "Tiempo de diseño"], ["Respuesta", "Modificar el código y probar el cambio"], ["Medida de la respuesta", "Menos de tres horas y sin efectos secundarios"]], "e": "Es el ejemplo de modificabilidad del apunte. La medida de la respuesta permite probar el escenario y determinar si el arquitecto logró el objetivo.", "inf": true, "ref": "apunte, págs. 26-27 y 31."},
  {"id": "ia-03-14", "unit": "b2", "t": "multi", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-14 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre las partes de un escenario de atributo de calidad son correctas? Seleccione todas las correctas.", "o": ["El entorno puede referirse a estados en los que el sistema no se está ejecutando, como desarrollo o pruebas.", "La fuente del estímulo puede afectar cómo el sistema lo trata.", "El artefacto es siempre el sistema completo.", "La respuesta no necesita ser medible para que el escenario sea válido.", "Un estímulo para la modificabilidad es una solicitud de modificación."], "a": [0, 1, 4], "e": "«El entorno puede referirse a estados en los que el sistema…»: lo dice el apunte de forma explícita.\n«La fuente del estímulo puede afectar cómo el sistema lo…»: un usuario confiable no se verifica igual que uno no confiable.\n«El artefacto es siempre el sistema completo.»: puede ser un conjunto de sistemas, el sistema completo o una o más partes.\n«La respuesta no necesita ser medible para que el escenario…»: la medida es lo que permite probar el escenario.\n«Un estímulo para la modificabilidad es una solicitud de…»: es el ejemplo del apunte.", "inf": true, "ref": "apunte, págs. 26-27."},
  {"id": "ia-03-15", "unit": "b2", "t": "multi", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-15 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre tácticas y patrones arquitectónicos.", "o": ["Aplicar un patrón garantiza mejorar todos los atributos sin compensaciones.", "Una táctica es una decisión de diseño que influye en el logro de la respuesta de un atributo de calidad.", "Un patrón describe un problema recurrente y una solución probada, con roles, responsabilidades y colaboraciones.", "Una táctica y un patrón son sinónimos: ambos abarcan una sola decisión.", "Los patrones suelen agrupar tácticas y, por eso, suelen implicar compensaciones entre atributos."], "a": [1, 2, 4], "e": "«Aplicar un patrón garantiza mejorar todos los atributos sin…»: contradice la idea de compensaciones.\n«Una táctica es una decisión de diseño que influye en el…»: es la definición del apunte.\n«Un patrón describe un problema recurrente y una solución…»: es la definición del apunte.\n«Una táctica y un patrón son sinónimos: ambos abarcan una…»: los patrones abarcan múltiples decisiones de diseño.\n«Los patrones suelen agrupar tácticas y, por eso, suelen…»: \"Con frecuencia implican compensaciones\".", "inf": true, "ref": "apunte, pág. 29."},
  {"id": "ia-03-16", "unit": "b2", "t": "rel", "tema": "Modificabilidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-16 · pregunta generada con IA", "q": "Empareje cada variante de modificabilidad con su descripción.", "i": [["Escalabilidad horizontal", "Agregar más unidades lógicas, como servidores adicionales."], ["Escalabilidad vertical", "Agregar más recursos a una unidad física, como más memoria."], ["Variabilidad", "Soportar la creación de variantes que difieren de manera planificada."], ["Portabilidad", "Adaptar con facilidad el software de una plataforma a otra."], ["Independencia de ubicación", "Interactuar sin conocer de antemano dónde está el otro componente."]], "e": "El apunte las presenta como nombres específicos para distintas variantes de modificabilidad.", "inf": true, "ref": "apunte, págs. 30-31."},
  {"id": "ia-03-17", "unit": "b2", "t": "multi", "tema": "Modificabilidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-17 · pregunta generada con IA", "q": "Un módulo concentra responsabilidades muy distintas, y un cambio en él suele impactar en varios módulos que dependen directamente de sus detalles internos. ¿Qué tácticas de modificabilidad son adecuadas? Seleccione todas las correctas.", "o": ["Introducir concurrencia procesando los eventos en hilos distintos.", "Usar un intermediario entre el módulo y quienes dependen de él.", "Mantener múltiples copias de los datos.", "Dividir el módulo en submódulos cohesivos y redistribuir responsabilidades.", "Encapsular el módulo y exponer una interfaz explícita."], "a": [1, 3, 4], "e": "«Introducir concurrencia procesando los eventos en hilos…» / «Mantener múltiples copias de los datos.»: son tácticas de rendimiento.\n«Usar un intermediario entre el módulo y quienes dependen de…»: es otra táctica para reducir el acoplamiento.\n«Dividir el módulo en submódulos cohesivos y redistribuir…»: es la táctica de aumentar la cohesión.\n«Encapsular el módulo y exponer una interfaz explícita.»: es una táctica para reducir el acoplamiento.", "inf": true, "ref": "apunte, págs. 32-33 y 37-38."},
  {"id": "ia-03-18", "unit": "b2", "t": "rel", "tema": "Modificabilidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-18 · pregunta generada con IA", "q": "Empareje cada mecanismo con el momento en que vincula los valores.", "i": [["Parametrización en tiempo de compilación", "Compilación o construcción"], ["Archivos de recursos", "Despliegue, inicio o inicialización"], ["Polimorfismo", "Tiempo de ejecución"]], "e": "En general, cuanto más tarde se fijan los valores, mejor, siempre que el mecanismo que lo permite sea rentable.", "inf": true, "ref": "apunte, pág. 33."},
  {"id": "ia-03-19", "unit": "b2", "t": "multi", "tema": "Rendimiento", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-19 · pregunta generada con IA", "q": "Según el apunte, ¿qué afirmaciones sobre el rendimiento son correctas? Seleccione todas las correctas.", "o": ["Cuando varios flujos compiten por el mismo recurso se genera latencia, y a mayor contención, mayor latencia.", "Las tácticas de rendimiento buscan siempre aumentar la cantidad de módulos.", "El tiempo de respuesta depende del tiempo de procesamiento y del tiempo bloqueado.", "Reducir la indirección puede mejorar el rendimiento, porque los intermediarios aumentan la sobrecarga computacional.", "El rendimiento solo puede abordarse después de construir el sistema; no se puede anticipar en la arquitectura."], "a": [0, 2, 3], "e": "«Cuando varios flujos compiten por el mismo recurso se…»: lo dice el apunte.\n«Las tácticas de rendimiento buscan siempre aumentar la…»: controlan el tiempo o los recursos usados para responder.\n«El tiempo de respuesta depende del tiempo de procesamiento…»: son los dos factores básicos que identifica el apunte.\n«Reducir la indirección puede mejorar el rendimiento, porque…»: muestra el compromiso con la modificabilidad, donde se recomienda usar intermediarios.\n«El rendimiento solo puede abordarse después de construir el…»: \"Esto puede anticiparse diseñando la arquitectura del sistema teniendo en mente el rendimiento\".", "inf": true, "ref": "apunte, págs. 35-37."},
  {"id": "ia-03-20", "unit": "b2", "t": "multi", "tema": "Rendimiento", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-20 · pregunta generada con IA", "q": "¿Cuáles de las siguientes son tácticas para gestionar los recursos disponibles (y no para controlar la demanda)? Seleccione todas las correctas.", "o": ["Mantener múltiples copias de los cálculos, por ejemplo con round robin.", "Introducir concurrencia.", "Disminuir la cantidad de cuadros de video procesados por segundo.", "Aumentar los recursos: procesadores más rápidos o más memoria.", "Descartar o poner en cola los eventos que excedan un límite."], "a": [0, 1, 3], "e": "«Mantener múltiples copias de los cálculos, por ejemplo con…» / «Introducir concurrencia.» / «Aumentar los recursos: procesadores más rápidos o más…»: usan los recursos de manera más eficiente para manejar la demanda.\n«Disminuir la cantidad de cuadros de video procesados por…» / «Descartar o poner en cola los eventos que excedan un límite.»: controlan la demanda, porque reducen el trabajo a procesar (frecuencia de muestreo y límite de respuesta a eventos).", "inf": true, "ref": "apunte, págs. 36-38."},
  {"id": "ia-03-21", "unit": "b2", "t": "rel", "tema": "Decisiones y vistas 4+1", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-21 · pregunta generada con IA", "q": "Según Sommerville, empareje cada requisito no funcional crítico con la decisión arquitectónica recomendada.", "i": [["Performance", "Pocos componentes grandes, con las operaciones críticas en una misma computadora."], ["Security", "Estructura en capas, con los activos más críticos en las capas internas."], ["Safety", "Ubicar las operaciones relacionadas en un único componente o en un conjunto pequeño."], ["Availability", "Incluir componentes redundantes para reemplazarlos sin detener el sistema."], ["Maintainability", "Usar componentes pequeños, modulares y autocontenidos."]], "e": "El apunte señala que estas decisiones pueden entrar en conflicto. Usar componentes grandes mejora el rendimiento, y usar componentes pequeños mejora la mantenibilidad. Puede resolverse con patrones distintos para distintas partes del sistema.", "inf": true, "ref": "apunte, págs. 41-42; Sommerville."},
  {"id": "ia-03-22", "unit": "b2", "t": "multi", "tema": "Decisiones y vistas 4+1", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-22 · pregunta generada con IA", "q": "Sobre el modelo de vistas \"4+1\" de Kruchten, marque las afirmaciones correctas.", "o": ["La vista de desarrollo muestra el hardware del sistema.", "La vista de procesos muestra el sistema en tiempo de ejecución como procesos que interactúan.", "Hofmeister et al. eliminan todas las vistas de Kruchten y solo conservan los escenarios.", "Las cuatro vistas se vinculan mediante casos de uso o escenarios comunes.", "La vista lógica muestra las abstracciones clave del sistema como objetos o clases."], "a": [1, 3, 4], "e": "«La vista de desarrollo muestra el hardware del sistema.»: esa es la vista física. La de desarrollo muestra cómo se descompone el software para su desarrollo.\n«La vista de procesos muestra el sistema en tiempo de…»: es la definición del apunte.\n«Hofmeister et al. eliminan todas las vistas de Kruchten y…»: hofmeister et al. proponen vistas similares y agregan una vista conceptual.\n«Las cuatro vistas se vinculan mediante casos de uso o…»: los escenarios son el \"+1\".\n«La vista lógica muestra las abstracciones clave del sistema…»: es la definición del apunte.", "inf": true, "ref": "apunte, págs. 42-43; Sommerville."},
  {"id": "ia-03-23", "unit": "b2", "t": "rel", "tema": "Estilos arquitectónicos (comparación)", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-23 · pregunta generada con IA", "q": "Empareje cada necesidad con el patrón arquitectónico más adecuado.", "i": [["MVC", "Hay múltiples maneras de ver e interactuar con los mismos datos."], ["Repositorio", "Grandes volúmenes de información que deben almacenarse durante mucho tiempo y a los que acceden varios componentes."], ["Tuberías y filtros", "Procesamiento por lotes en etapas separadas, con poca interacción con el usuario."], ["Cliente-servidor", "Una base de datos compartida debe accederse desde distintas ubicaciones y la carga varía."], ["Microkernel", "Un sistema central mínimo debe poder extenderse con funcionalidades adicionales independientes."]], "e": "Son los casos de uso que indica el apunte en la tabla de cada patrón. Chrome con sus extensiones es el ejemplo de microkernel que da el apunte.", "inf": true, "ref": "apunte, págs. 43-49; Sommerville."},
  {"id": "ia-03-24", "unit": "b2", "t": "multi", "tema": "Estilos arquitectónicos (comparación)", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-24 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre las desventajas de los patrones arquitectónicos son correctas? Seleccione todas las correctas.", "o": ["En cliente-servidor, el rendimiento es siempre predecible porque no depende de la red.", "En tuberías y filtros, el formato de los datos debe acordarse entre transformaciones, lo que dificulta reutilizar componentes incompatibles.", "MVC siempre simplifica el código, incluso en datos e interacciones simples.", "En la arquitectura en capas, el rendimiento puede ser un problema por la latencia entre capas.", "El repositorio es un punto único de fallo."], "a": [1, 3, 4], "e": "«En cliente-servidor, el rendimiento es siempre predecible…»: el rendimiento es impredecible por la latencia de la red y del sistema.\n«En tuberías y filtros, el formato de los datos debe…»: es la desventaja que señala la tabla del patrón.\n«MVC siempre simplifica el código, incluso en datos e…»: puede involucrar código y complejidad adicional en casos simples.\n«En la arquitectura en capas, el rendimiento puede ser un…»: además, en la práctica es difícil separar claramente las capas.\n«El repositorio es un punto único de fallo.»: los problemas del repositorio afectan a todo el sistema.", "inf": true, "ref": "apunte, págs. 43-48."},
  {"id": "ia-03-25", "unit": "b2", "t": "multi", "tema": "Atributos y escenarios de calidad", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 03-25 · pregunta generada con IA", "q": "Las clases teóricas presentan los modelos de calidad de McCall e ISO 25010. El apunte de Celina no los desarrolla. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["En McCall, la portabilidad pertenece a la operación del producto.", "McCall organiza los factores en tres perspectivas: operación, revisión y transición del producto.", "En McCall, la mantenibilidad, la flexibilidad y la testabilidad pertenecen a la revisión del producto.", "El modelo de calidad del producto de ISO 25010 tiene ocho características, entre ellas seguridad, compatibilidad y portabilidad.", "ISO 25010 define una única perspectiva, sin distinguir calidad en uso y calidad del producto."], "a": [1, 2, 3], "e": "«En McCall, la portabilidad pertenece a la operación del…»: la portabilidad pertenece a la transición del producto.\n«McCall organiza los factores en tres perspectivas:…»: son las tres perspectivas de McCall y Walters (1977).\n«En McCall, la mantenibilidad, la flexibilidad y la…»: reflejan la capacidad de sufrir cambios.\n«El modelo de calidad del producto de ISO 25010 tiene ocho…»: las ocho son adecuación funcional, eficiencia de desempeño, compatibilidad, usabilidad, fiabilidad, seguridad, mantenibilidad y portabilidad.\n«ISO 25010 define una única perspectiva, sin distinguir…»: ISO 25010 distingue el modelo de calidad en uso y el de calidad del producto.", "inf": true, "ref": "Powers de Clase; Pressman y Maxim. No figura en el apunte de Celina."},
  {"id": "ia-04-04", "unit": "b2", "t": "multi", "tema": "Sistemas distribuidos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-04 · pregunta generada con IA", "q": "Según Coulouris, citado en el apunte, ¿cuáles de los siguientes son beneficios de un sistema distribuido? Seleccione todas las correctas.", "o": ["Uso compartido de recursos de hardware y software.", "Mayor facilidad para diseñar, implementar y probar.", "Menor complejidad que un sistema centralizado.", "Apertura, gracias al diseño en torno a protocolos estándar.", "Tolerancia a fallos, por la replicación de información y la disponibilidad de múltiples computadoras."], "a": [0, 3, 4], "e": "«Uso compartido de recursos de hardware y software.»: es el uso compartido.\n«Mayor facilidad para diseñar, implementar y probar.»: el apunte dice que son más difíciles de diseñar, implementar y probar.\n«Menor complejidad que un sistema centralizado.»: son intrínsecamente más complejos que los centralizados.\n«Apertura, gracias al diseño en torno a protocolos estándar.»: permite combinar equipos y software de distintos proveedores.\n«Tolerancia a fallos, por la replicación de información y la…»: es la tolerancia a fallos.", "inf": true, "ref": "apunte, págs. 50-51."},
  {"id": "ia-04-05", "unit": "b2", "t": "multi", "tema": "Sistemas distribuidos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-05 · pregunta generada con IA", "q": "Una empresa quiere que su sistema distribuido crezca en usuarios y se extienda a varios países, con partes gestionadas por otras organizaciones. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["La escalabilidad se refiere solo a agregar memoria a un servidor.", "El tamaño se relaciona con poder agregar recursos para más usuarios.", "En la práctica, la administrabilidad suele ser el factor que limita la escalabilidad.", "Las partes en organizaciones independientes no afectan la escalabilidad.", "La distribución se relaciona con repartir componentes geográficamente sin degradar el rendimiento."], "a": [1, 2, 4], "e": "«La escalabilidad se refiere solo a agregar memoria a un…»: eso es solo el escalamiento vertical.\n«El tamaño se relaciona con poder agregar recursos para más…» / «La distribución se relaciona con repartir componentes…»: son dos de las tres dimensiones.\n«En la práctica, la administrabilidad suele ser el factor…»: lo afirma el apunte.\n«Las partes en organizaciones independientes no afectan la…»: la administrabilidad contempla precisamente ese caso.", "inf": true, "ref": "apunte, pág. 51; Sommerville."},
  {"id": "ia-04-06", "unit": "b2", "t": "rel", "tema": "Sistemas distribuidos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-06 · pregunta generada con IA", "q": "Empareje cada tipo de ataque a un sistema distribuido con su ejemplo.", "i": [["Intercepción", "Un atacante accede a las comunicaciones entre partes del sistema y lee información confidencial."], ["Interrupción", "Un ataque de denegación de servicio impide que el servicio se entregue como se espera."], ["Modificación", "Un atacante altera los datos almacenados en el sistema."], ["Fabricación", "Un atacante inserta transacciones falsas que no deberían existir."]], "e": "El apunte enumera los cuatro tipos sin definirlos. Las definiciones salen de Sommerville y afectan, respectivamente, la confidencialidad, la disponibilidad, la integridad y la autenticidad de la información.", "inf": true, "ref": "apunte, pág. 51; Sommerville."},
  {"id": "ia-04-07", "unit": "b2", "t": "rel", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-07 · pregunta generada con IA", "q": "Empareje cada situación con el patrón arquitectónico para sistemas distribuidos más adecuado.", "i": [["Maestro-esclavo", "Sistema de tiempo real que debe garantizar tiempos de respuesta de interacción."], ["Cliente-servidor de dos niveles", "Sistema simple que conviene centralizar por motivos de seguridad."], ["Cliente-servidor multinivel", "El servidor debe procesar un alto volumen de transacciones."], ["Componentes distribuidos", "Hay que combinar recursos provenientes de distintos sistemas y bases de datos."], ["Peer-to-peer", "Los clientes intercambian información almacenada localmente, y el servidor solo los conecta."]], "e": "Son los usos que el apunte indica para cada uno de los cinco patrones.", "inf": true, "ref": "apunte, pág. 53; Sommerville."},
  {"id": "ia-04-08", "unit": "b2", "t": "multi", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-08 · pregunta generada con IA", "q": "Un sistema de control de tráfico urbano tiene un proceso en el centro de control, un proceso que recoge datos de sensores y otro que gestiona los semáforos. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["El proceso del centro de control actúa como maestro.", "Los procesos que recogen datos y gestionan semáforos actúan como esclavos.", "Este patrón es incompatible con los sistemas de tiempo real.", "El patrón es adecuado para procesamiento distribuido predecible, con requisitos de alto rendimiento o tolerancia a fallos.", "Todos los procesos deben ser idénticos e intercambiables, sin distinción de roles."], "a": [0, 1, 3], "e": "«El proceso del centro de control actúa como maestro.» / «Los procesos que recogen datos y gestionan semáforos actúan…»: es el ejemplo del apunte.\n«Este patrón es incompatible con los sistemas de tiempo real.»: es común en sistemas de tiempo real con plazos de procesamiento.\n«El patrón es adecuado para procesamiento distribuido…»: lo dice el apunte. También es común en replicación de bases de datos.\n«Todos los procesos deben ser idénticos e intercambiables,…»: los esclavos se dedican a acciones específicas.", "inf": true, "ref": "apunte, págs. 53-54; Sommerville."},
  {"id": "ia-04-09", "unit": "b2", "t": "multi", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-09 · pregunta generada con IA", "q": "Una empresa con miles de puestos de trabajo evalúa un cliente-servidor de dos niveles. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["El cliente liviano es fácil de administrar, pero impone una alta carga al servidor y a la red.", "Con cliente liviano se reduce el tráfico de red, porque el procesamiento se hace en el cliente.", "Con cliente liviano, solo la presentación está en el cliente y el resto en el servidor.", "El cliente pesado aprovecha el procesamiento local, pero exige instalar y mantener software en cada computadora.", "Con cliente pesado, la base de datos debe residir en cada cliente."], "a": [0, 2, 3], "e": "«El cliente liviano es fácil de administrar, pero impone una…»: puede requerir más inversión en capacidad de red y de servidor.\n«Con cliente liviano se reduce el tráfico de red, porque el…»: es al revés: el servidor hace el cómputo y genera gran tráfico.\n«Con cliente liviano, solo la presentación está en el…»: es la definición del modelo.\n«El cliente pesado aprovecha el procesamiento local, pero…»: implica una gestión más compleja.\n«Con cliente pesado, la base de datos debe residir en cada…»: la gestión y la base de datos permanecen en el servidor.", "inf": true, "ref": "apunte, págs. 54-55."},
  {"id": "ia-04-10", "unit": "b2", "t": "multi", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-10 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones justifican usar una arquitectura cliente-servidor multinivel en lugar de una de dos niveles? Seleccione todas las correctas.", "o": ["En multinivel, cada nivel puede administrarse de manera independiente y agregar servidores según la carga.", "En multinivel todas las capas deben ejecutarse en el mismo procesador.", "Distribuir el procesamiento entre la lógica de aplicación y la gestión de datos reduce los tiempos de respuesta.", "En dos niveles, las capas lógicas deben asignarse solo a dos sistemas: cliente y servidor.", "El multinivel elimina la necesidad de la capa de presentación."], "a": [0, 2, 3], "e": "«En multinivel, cada nivel puede administrarse de manera…»: por eso es más escalable.\n«En multinivel todas las capas deben ejecutarse en el mismo…»: las capas se implementan como procesos independientes que pueden estar en distintos procesadores.\n«Distribuir el procesamiento entre la lógica de aplicación y…»: lo dice el apunte.\n«En dos niveles, las capas lógicas deben asignarse solo a…»: es el problema fundamental que señala el apunte.\n«El multinivel elimina la necesidad de la capa de…»: la presentación sigue siendo una capa lógica.", "inf": true, "ref": "apunte, págs. 55-56."},
  {"id": "ia-04-11", "unit": "b2", "t": "multi", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-11 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre las arquitecturas de componentes distribuidos.", "o": ["Permiten retrasar las decisiones sobre dónde y cómo proporcionar los servicios.", "Son más simples de diseñar que los sistemas cliente-servidor.", "Existen estándares universales de middleware adoptados por todos los proveedores.", "Los componentes acceden a los servicios de otros mediante middleware, con llamadas remotas.", "Fueron en gran medida reemplazadas por SOA, aunque conservan ventajas de rendimiento."], "a": [0, 3, 4], "e": "«Permiten retrasar las decisiones sobre dónde y cómo…»: los componentes pueden ejecutarse en cualquier nodo.\n«Son más simples de diseñar que los sistemas…»: son más complejas de diseñar.\n«Existen estándares universales de middleware adoptados por…»: no hay estándares universales; Microsoft y Sun desarrollaron soluciones incompatibles.\n«Los componentes acceden a los servicios de otros mediante…»: el middleware gestiona las interacciones.\n«Fueron en gran medida reemplazadas por SOA, aunque…»: lo dice el apunte.", "inf": true, "ref": "apunte, págs. 56-57."},
  {"id": "ia-04-12", "unit": "b2", "t": "multi", "tema": "Topologías distribuidas", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-12 · pregunta generada con IA", "q": "¿En qué casos o bajo qué afirmaciones es correcto hablar de una arquitectura peer-to-peer? Seleccione todas las correctas.", "o": ["En la variante semicentralizada, uno o varios nodos actúan como superpares para facilitar la comunicación y reducir el tráfico.", "Un sistema bancario comercial que requiere una seguridad centralizada estricta.", "Un sistema computacionalmente intensivo que puede dividirse en muchas tareas independientes, como el análisis de millones de moléculas.", "Un sistema de intercambio de archivos entre computadoras, sin almacenamiento centralizado.", "Una arquitectura donde cada nodo solo puede actuar como cliente."], "a": [0, 2, 3], "e": "«En la variante semicentralizada, uno o varios nodos actúan…»: es la arquitectura semicentralizada.\n«Un sistema bancario comercial que requiere una seguridad…»: el apunte dice que P2P es malo en seguridad, y más apto para sistemas personales que comerciales.\n«Un sistema computacionalmente intensivo que puede dividirse…» / «Un sistema de intercambio de archivos entre computadoras,…»: son los dos casos que señala el apunte.\n«Una arquitectura donde cada nodo solo puede actuar como…»: en principio, no hay distinción entre cliente y servidor.", "inf": true, "ref": "apunte, págs. 57-58; Sommerville."},
  {"id": "ia-04-13", "unit": "b2", "t": "multi", "tema": "SOA", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-13 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre las arquitecturas orientadas a servicios.", "o": ["A diferencia de un componente, un servicio web no tiene una interfaz \"requiere\".", "Las aplicaciones pueden cambiar dinámicamente de proveedor durante la ejecución.", "Un cliente debe conocer la implementación interna de un servicio para poder usarlo.", "Los servicios son independientes de la plataforma y del lenguaje de implementación.", "Los servicios son accedidos principalmente por usuarios finales, no por otros programas."], "a": [0, 1, 3], "e": "«A diferencia de un componente, un servicio web no tiene una…»: solo implementa \"provee\" y no depende de otros componentes.\n«Las aplicaciones pueden cambiar dinámicamente de proveedor…»: es una de las ventajas listadas.\n«Un cliente debe conocer la implementación interna de un…»: un servicio se describe con metadatos procesables por máquina, sin exponer su implementación.\n«Los servicios son independientes de la plataforma y del…»: es la definición del apunte.\n«Los servicios son accedidos principalmente por usuarios…»: \"Son accedidos por otros programas en vez de usuarios\".", "inf": true, "ref": "apunte, págs. 58-60."},
  {"id": "ia-04-14", "unit": "b2", "t": "rel", "tema": "SOA", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-14 · pregunta generada con IA", "q": "Empareje cada estándar de servicios web con su propósito.", "i": [["SOAP", "Intercambio de mensajes entre servicios."], ["WSDL", "Definición de interfaces de servicio, sus operaciones y enlaces."], ["WS-BPEL", "Lenguaje de flujo de trabajo para procesos que involucran varios servicios."], ["UDDI", "Descubrimiento de la existencia de un servicio."]], "e": "Son los cuatro estándares principales del apunte, que marca a UDDI como en desuso.", "inf": true, "ref": "apunte, pág. 60."},
  {"id": "ia-04-15", "unit": "b2", "t": "multi", "tema": "Microservicios", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-15 · pregunta generada con IA", "q": "Una tienda en línea migra desde un monolito a microservicios porque cada cambio obliga a reconstruir todo y la demanda aumenta solo en el servicio de pagos. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Se pueden crear réplicas del servicio de pagos sin un servidor más potente, y escalar horizontalmente suele ser más económico.", "El API Gateway actúa como punto único de contacto y permite reorganizar los servicios sin afectar al cliente.", "Todos los microservicios deben desplegarse juntos en cada versión.", "Cada microservicio puede escribirse en un lenguaje distinto y usar otra tecnología de almacenamiento.", "El sistema resultante es más simple de manejar, porque tiene menos módulos."], "a": [0, 1, 3], "e": "«Se pueden crear réplicas del servicio de pagos sin un…»: es el \"scale out\" del apunte.\n«El API Gateway actúa como punto único de contacto y permite…»: la aplicación tampoco necesita saber qué protocolo se usa entre los servicios.\n«Todos los microservicios deben desplegarse juntos en cada…»: son desplegables de forma independiente.\n«Cada microservicio puede escribirse en un lenguaje distinto…»: es la independencia de la implementación.\n«El sistema resultante es más simple de manejar, porque…»: el apunte aclara que es más compleja de manejar, porque hay más módulos.", "inf": true, "ref": "apunte, págs. 60-61; Cap. 6 Microservicios (Sommerville)."},
  {"id": "ia-04-16", "unit": "b2", "t": "multi", "tema": "SaaS", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 04-16 · pregunta generada con IA", "q": "Las clases teóricas distinguen SaaS de SOA. El apunte de Celina no desarrolla esta distinción. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["En SaaS el usuario debe instalar y administrar el software en su propia computadora.", "SaaS es un modelo de entrega de aplicaciones al usuario final; SOA es un estilo de arquitectura.", "SaaS y SOA son sinónimos: todo SaaS debe construirse necesariamente con SOA.", "SaaS suele mantener el estado de sesión durante transacciones largas, mientras que los servicios de SOA suelen ser sin estado."], "a": [1, 3], "e": "«En SaaS el usuario debe instalar y administrar el software…»: el software se aloja en servidores del proveedor y se accede por la Web.\n«SaaS es un modelo de entrega de aplicaciones al usuario…»: es la diferencia de propósito.\n«SaaS y SOA son sinónimos: todo SaaS debe construirse…»: un SaaS no requiere estar construido con SOA.\n«SaaS suele mantener el estado de sesión durante…»: es la diferencia en gestión de estado.", "inf": true, "ref": "Powers de Clase; Sommerville. No figura en el apunte de Celina."},
  {"id": "ia-05-13", "unit": "b3", "t": "rel", "tema": "PUDS: fases e hitos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-13 · pregunta generada con IA", "q": "Empareje cada fase del Proceso Unificado con el hito con el que finaliza.", "i": [["Inicio", "Objetivos del ciclo de vida"], ["Elaboración", "Arquitectura del ciclo de vida"], ["Construcción", "Capacidad operativa inicial"], ["Transición", "Lanzamiento del producto"]], "e": "Cada fase finaliza con un hito que marca la disponibilidad de ciertos artefactos y permite tomar decisiones clave.", "inf": true, "ref": "apunte, págs. 65-67; PUDS."},
  {"id": "ia-05-14", "unit": "b3", "t": "multi", "tema": "PUDS: fases e hitos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-14 · pregunta generada con IA", "q": "Un equipo acaba de entregar una versión beta a usuarios reales, corrige los defectos críticos y deja los menores para una versión posterior. Además, capacita a los usuarios y prepara el soporte. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Es en esta fase cuando se identifican por primera vez los riesgos más importantes.", "El proyecto está en la fase de transición.", "Al finalizar la fase se alcanza el hito de lanzamiento del producto, con acuerdo del cliente.", "El proyecto está en la fase de elaboración, porque se estabiliza la arquitectura."], "a": [1, 2], "e": "«Es en esta fase cuando se identifican por primera vez los…»: eso ocurre en la fase de inicio.\n«El proyecto está en la fase de transición.»: el producto pasa a beta y se prueba con usuarios reales. Incluye capacitación, soporte y mantenimiento.\n«Al finalizar la fase se alcanza el hito de lanzamiento del…»: es el hito de la transición.\n«El proyecto está en la fase de elaboración, porque se…»: la arquitectura se estabiliza mucho antes.", "inf": true, "ref": "apunte, págs. 65-67."},
  {"id": "ia-05-15", "unit": "b3", "t": "multi", "tema": "PUDS: visión general", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-15 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre las tres características clave del Proceso Unificado.", "o": ["Dirigido por casos de uso significa que los casos de uso guían el diseño, la implementación y la prueba.", "Primero se termina toda la arquitectura y recién después se empieza a pensar en los casos de uso.", "Los casos de uso guían la arquitectura, y la arquitectura influye en la selección de los casos de uso.", "Cada iteración resulta en un incremento y debe estar planificada.", "Si una iteración falla, se pierde el producto entero."], "a": [0, 2, 3], "e": "«Dirigido por casos de uso significa que los casos de uso…»: son el hilo conductor del proceso.\n«Primero se termina toda la arquitectura y recién después se…»: deben evolucionar en paralelo.\n«Los casos de uso guían la arquitectura, y la arquitectura…»: ambos maduran según avanza el ciclo.\n«Cada iteración resulta en un incremento y debe estar…»: las iteraciones deben estar controladas.\n«Si una iteración falla, se pierde el producto entero.»: el riesgo se reduce a los costos de un solo incremento.", "inf": true, "ref": "apunte, págs. 62-63."},
  {"id": "ia-05-16", "unit": "b3", "t": "rel", "tema": "PUDS: visión general", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-16 · pregunta generada con IA", "q": "Empareje cada elemento de las \"4P + H\" con su definición. El apunte de Celina no desarrolla este tema.", "i": [["Personas", "Arquitectos, desarrolladores, ingenieros de prueba, usuarios y otros interesados."], ["Proyecto", "Elemento organizativo a través del cual se gestiona el desarrollo; su resultado es una versión de un producto."], ["Producto", "Artefactos creados durante la vida del proyecto: modelos, código fuente, ejecutables y documentación."], ["Proceso", "Plantilla con las actividades necesarias para transformar los requisitos en un producto."], ["Herramientas", "Software que automatiza las actividades definidas."]], "e": "El libro compara proceso y proyecto con clase e instancia: el proceso es la plantilla, y el proyecto, su instancia concreta. El producto es más que código, porque incluye todos los modelos.", "inf": true, "ref": "PUDS, cap. 2; Powers de Clase. No figura en el apunte de Celina."},
  {"id": "ia-05-17", "unit": "b3", "t": "multi", "tema": "Requisitos y contexto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-17 · pregunta generada con IA", "q": "Sobre la comprensión del contexto y los requisitos en el flujo de requisitos, marque las afirmaciones correctas.", "o": ["El modelado del dominio describe objetos del dominio, y el del negocio describe procesos.", "Un requisito adicional es un requisito no funcional que no puede asociarse a un caso de uso en concreto.", "El glosario es más formal y más difícil de mantener que un modelo de negocio.", "El arquitecto y el jefe de proyecto deciden si se prepara un modelo del dominio, uno de negocio o ninguno.", "La lista de características debe mantenerse como artefacto final y permanente del sistema."], "a": [0, 1, 3], "e": "«El modelado del dominio describe objetos del dominio, y el…»: son las dos aproximaciones para expresar el contexto.\n«Un requisito adicional es un requisito no funcional que no…»: su impacto puede abarcar cero o muchos casos de uso.\n«El glosario es más formal y más difícil de mantener que un…»: es menos formal y más fácil de mantener.\n«El arquitecto y el jefe de proyecto deciden si se prepara…»: lo dice el apunte de forma explícita.\n«La lista de características debe mantenerse como artefacto…»: no es un artefacto final y permanente. El apunte dice que se usa solo para planificar el trabajo.", "inf": true, "nota": "el apunte (pág. 68) dice que la lista de características \"se utiliza solo para la planificación del trabajo\". NotebookLM (PUDS, cap. 6 y §7.4.1) agrega que también es entrada de \"Encontrar actores y casos de uso\". La opción e es falsa en ambos casos.", "ref": "apunte, págs. 67-70 y 73."},
  {"id": "ia-05-18", "unit": "b3", "t": "multi", "tema": "Flujo de Requisitos", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-18 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre actores y casos de uso son correctas? Seleccione todas las correctas.", "o": ["Un caso de uso debe ejecutarse siempre como continuación de otro caso de uso.", "Un caso de uso entrega un resultado observable que añade valor a un actor concreto.", "Un sistema externo con el que interactúa el sistema también se representa como actor.", "Las instancias de caso de uso interactúan entre sí mediante atributos compartidos.", "Las instancias de caso de uso son atómicas: se ejecutan por completo o no se ejecutan."], "a": [1, 2, 4], "e": "«Un caso de uso debe ejecutarse siempre como continuación de…»: deberían ser completos por sí mismos.\n«Un caso de uso entrega un resultado observable que añade…»: es una condición para encontrar casos de uso.\n«Un sistema externo con el que interactúa el sistema también…»: cada sistema externo se representa como actor.\n«Las instancias de caso de uso interactúan entre sí mediante…»: los atributos son locales, y las instancias no tienen interacción con otras.\n«Las instancias de caso de uso son atómicas: se ejecutan por…»: lo dice el apunte de forma explícita.", "inf": true, "ref": "apunte, págs. 72 y 76-77."},
  {"id": "ia-05-19", "unit": "b3", "t": "rel", "tema": "Modelo de Análisis", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-19 · pregunta generada con IA", "q": "En el caso de uso \"Sacar dinero\" de un cajero automático, se identifican estas clases de análisis. Empareje cada una con su estereotipo.", "i": [["InterfazCajero, ventana con la que interactúa el cliente", "Interfaz (frontera)"], ["Retirada, que coordina la secuencia de pasos del caso de uso", "Control"], ["Cuenta, que guarda el saldo y las operaciones asociadas", "Entidad"]], "e": "Las clases de interfaz modelan la interacción con los actores. Las de control representan coordinación, secuencia y transacciones. Las de entidad modelan información y comportamiento de un fenómeno o concepto.", "inf": true, "ref": "apunte, pág. 84; PUDS."},
  {"id": "ia-05-20", "unit": "b3", "t": "multi", "tema": "Flujo de Análisis", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-20 · pregunta generada con IA", "q": "Durante la actividad \"Analizar un caso de uso\", ¿qué normas o afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Los mensajes del diagrama deben asociarse a operaciones concretas de un lenguaje de programación.", "Se identifica una clase de interfaz central para cada actor humano.", "Se identifica una clase de control responsable de coordinar la realización del caso de uso.", "La secuencia del diagrama debe ser el objetivo principal.", "Cada clase de análisis identificada debería tener al menos un objeto que participe en un diagrama de colaboración."], "a": [1, 2, 4], "e": "«Los mensajes del diagrama deben asociarse a operaciones…»: en análisis, \"los mensajes no se asocian a operaciones\".\n«Se identifica una clase de interfaz central para cada actor…» / «Se identifica una clase de control responsable de coordinar…»: son normas para identificar clases de análisis.\n«La secuencia del diagrama debe ser el objetivo principal.»: \"la secuencia en el diagrama no debería ser nuestro objetivo principal\".\n«Cada clase de análisis identificada debería tener al menos…»: es una regla del diagrama de colaboración.", "inf": true, "ref": "apunte, págs. 89-90."},
  {"id": "ia-05-21", "unit": "b3", "t": "multi", "tema": "Modelo de Análisis", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 05-21 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre los paquetes del modelo de análisis.", "o": ["Un paquete de servicio es indivisible: el sistema lo ofrece entero o nada.", "Los paquetes de servicio siempre se identifican antes de comenzar el análisis.", "Los paquetes de análisis deberían ser cohesivos y débilmente acoplados.", "Los casos de uso son para los usuarios y los servicios son para los clientes.", "Un paquete de análisis no puede contener otros paquetes de análisis."], "a": [0, 2, 3], "e": "«Un paquete de servicio es indivisible: el sistema lo ofrece…»: lo dice el apunte de forma explícita.\n«Los paquetes de servicio siempre se identifican antes de…»: suele hacerse cuando el trabajo de análisis está avanzado.\n«Los paquetes de análisis deberían ser cohesivos y…»: es una característica que da el apunte.\n«Los casos de uso son para los usuarios y los servicios son…»: lo dice el apunte de forma explícita.\n«Un paquete de análisis no puede contener otros paquetes de…»: puede contener otros paquetes de forma recursiva.", "inf": true, "ref": "apunte, págs. 86 y 88."},
  {"id": "ia-06-09", "unit": "b3", "t": "rel", "tema": "Modelo de Diseño", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-09 · pregunta generada con IA", "q": "Empareje cada característica con el modelo al que corresponde.", "i": [["Genérico respecto al diseño y con tres estereotipos conceptuales.", "Modelo de análisis"], ["Puede no estar mantenido durante todo el ciclo de vida.", "Modelo de análisis"], ["Es un plano de la implementación y es más caro de desarrollar.", "Modelo de diseño"], ["Creado principalmente como programación visual en ingeniería de ida y vuelta.", "Modelo de diseño"]], "e": "El modelo de análisis es conceptual y menos formal, un bosquejo del diseño. El de diseño es físico, más formal, y debe mantenerse durante todo el ciclo de vida.", "inf": true, "ref": "apunte, págs. 93-94."},
  {"id": "ia-06-10", "unit": "b3", "t": "multi", "tema": "Modelo de Diseño", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-10 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre la realización de caso de uso-diseño.", "o": ["Los flujos de sucesos-diseño deberían mencionar todos los atributos y las operaciones de cada clase.", "Se describe mediante diagramas de clases, diagramas de interacción y flujos de sucesos-diseño.", "Proporciona una traza directa a una realización de caso de uso-análisis.", "En sus diagramas de secuencia, la secuencia de mensajes debe ser la principal preocupación.", "Se prefieren los diagramas de colaboración porque la secuencia no importa."], "a": [1, 2, 3], "e": "«Los flujos de sucesos-diseño deberían mencionar todos los…»: no deberían mencionarlos, porque son difíciles de mantener.\n«Se describe mediante diagramas de clases, diagramas de…»: también recoge requisitos de implementación.\n«Proporciona una traza directa a una realización de caso de…»: es la definición del apunte.\n«En sus diagramas de secuencia, la secuencia de mensajes…»: es la diferencia con el análisis.\n«Se prefieren los diagramas de colaboración porque la…»: esa preferencia corresponde al análisis.", "inf": true, "ref": "apunte, págs. 90, 96 y 103."},
  {"id": "ia-06-11", "unit": "b3", "t": "multi", "tema": "Modelo de Diseño", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-11 · pregunta generada con IA", "q": "Un sistema incluye un producto de terceros encapsulado y un servicio opcional identificado en el análisis. ¿Qué afirmaciones sobre los subsistemas de diseño son correctas? Seleccione todas las correctas.", "o": ["Un subsistema de servicio debe contener exactamente las mismas clases que su paquete de servicio.", "Los subsistemas de servicio se basan en los paquetes de servicio del análisis, y normalmente hay una traza uno a uno.", "Un subsistema de servicio suele dar lugar a un componente ejecutable o binario en la implementación.", "Los subsistemas de diseño deberían ser poco cohesivos y fuertemente acoplados, para centralizar el control.", "Un subsistema de diseño puede representar productos de software reutilizados que han sido encapsulados, o sistemas heredados."], "a": [1, 2, 4], "e": "«Un subsistema de servicio debe contener exactamente las…»: puede contener más clases, porque maneja requisitos no funcionales.\n«Los subsistemas de servicio se basan en los paquetes de…»: lo dice el apunte de forma explícita.\n«Un subsistema de servicio suele dar lugar a un componente…»: lo dice el apunte de forma explícita.\n«Los subsistemas de diseño deberían ser poco cohesivos y…»: deberían ser cohesivos y débilmente acoplados.\n«Un subsistema de diseño puede representar productos de…»: son características que da el apunte.", "inf": true, "ref": "apunte, pág. 97."},
  {"id": "ia-06-12", "unit": "b3", "t": "multi", "tema": "Modelo de Diseño", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-12 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre el modelo de despliegue son correctas? Seleccione todas las correctas.", "o": ["Solo puede describir la configuración de producción.", "La funcionalidad de un nodo se define por los componentes que se distribuyen sobre él.", "Representa una correspondencia entre la arquitectura de software y la arquitectura del sistema (hardware).", "Cada nodo representa un recurso de cómputo, normalmente un procesador o un dispositivo similar.", "El arquitecto no tiene responsabilidad sobre este modelo."], "a": [1, 2, 3], "e": "«Solo puede describir la configuración de producción.»: también puede describir configuraciones para pruebas y para simulación.\n«La funcionalidad de un nodo se define por los componentes…» / «Representa una correspondencia entre la arquitectura de…» / «Cada nodo representa un recurso de cómputo, normalmente un…»: son características que da el apunte.\n«El arquitecto no tiene responsabilidad sobre este modelo.»: el arquitecto es responsable de la integridad de los modelos de diseño y despliegue.", "inf": true, "ref": "apunte, págs. 98-99."},
  {"id": "ia-06-13", "unit": "b3", "t": "rel", "tema": "Flujo de Diseño", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-13 · pregunta generada con IA", "q": "Al esbozar una clase de diseño a partir de una clase de análisis, el método depende del estereotipo. Empareje cada estereotipo con lo que implica diseñarlo.", "i": [["Clase de interfaz", "Depende de la tecnología de interfaz específica que se utilice."], ["Clase de entidad", "A menudo implica usar tecnologías de base de datos específicas."], ["Clase de control", "Es una tarea delicada: hay que considerar distribución, rendimiento y transacciones."]], "e": "Las clases de diseño identificadas deberían trazarse hacia las clases de análisis correspondientes.", "inf": true, "ref": "apunte, pág. 105; PUDS, cap. 9."},
  {"id": "ia-06-14", "unit": "b3", "t": "rel", "tema": "Implementación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-14 · pregunta generada con IA", "q": "Empareje cada estereotipo estándar de componente con su significado.", "i": [["<<executable>>", "Programa que puede ser ejecutado en un nodo."], ["<<file>>", "Fichero con código fuente o datos."], ["<<library>>", "Librería estática o dinámica."], ["<<table>>", "Tabla de base de datos."], ["<<document>>", "Documento."]], "e": "Un componente es el empaquetamiento físico de los elementos de un modelo. Es normal que implemente varios elementos.", "inf": true, "ref": "apunte, pág. 109."},
  {"id": "ia-06-15", "unit": "b3", "t": "multi", "tema": "Implementación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-15 · pregunta generada con IA", "q": "Un integrador de sistemas planifica las construcciones de una iteración. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Una construcción debería añadir funcionalidad a la previa e implementar casos de uso completos o escenarios de estos.", "Un stub es un componente con implementación esquelética que permite desarrollar o probar otro que depende de él.", "Una construcción debería incluir la mayor cantidad posible de componentes nuevos, para acelerar el avance.", "Una construcción es una versión ejecutable del sistema, usualmente una parte específica.", "Cada construcción pasa a la siguiente sin pruebas de integración, y se prueba todo junto al final del proyecto."], "a": [0, 1, 3], "e": "«Una construcción debería añadir funcionalidad a la previa e…»: es un criterio para crear una construcción.\n«Un stub es un componente con implementación esquelética que…»: simplifica los problemas de integración y las pruebas.\n«Una construcción debería incluir la mayor cantidad posible…»: no debería incluir demasiados componentes nuevos o refinados.\n«Una construcción es una versión ejecutable del sistema,…»: es la definición del apunte.\n«Cada construcción pasa a la siguiente sin pruebas de…»: cada construcción se somete a pruebas de integración antes de crear otra.", "inf": true, "ref": "apunte, págs. 110-112 y 114-115."},
  {"id": "ia-06-16", "unit": "b3", "t": "rel", "tema": "Implementación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-16 · pregunta generada con IA", "q": "Empareje cada responsabilidad con el trabajador del flujo de implementación.", "i": [["Asignar los componentes ejecutables a nodos.", "Arquitecto"], ["Definir y mantener el código fuente de uno o varios componentes.", "Ingeniero de componentes"], ["Planificar la secuencia de construcciones necesarias en cada iteración.", "Integrador de sistemas"]], "e": "El arquitecto también es responsable de la integridad del modelo de implementación. La planificación del integrador da lugar a un plan de integración de construcciones.", "inf": true, "ref": "apunte, pág. 112."},
  {"id": "ia-06-17", "unit": "b3", "t": "rel", "tema": "Prueba", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-17 · pregunta generada con IA", "q": "Empareje cada artefacto del flujo de prueba con su definición.", "i": [["Caso de prueba", "Especifica una forma de probar el sistema: qué entrada usar y bajo qué condiciones."], ["Procedimiento de prueba", "Especifica cómo realizar uno o varios casos de prueba, o partes de ellos."], ["Componente de prueba", "Automatiza uno o varios procedimientos de prueba, o partes de ellos."], ["Plan de prueba", "Describe las estrategias, los recursos y la planificación de la prueba."], ["Defecto", "Anomalía del sistema, como un síntoma de un fallo de software."], ["Evaluación de prueba", "Analiza resultados como la cobertura de los casos de prueba, la cobertura de código y el estado de los defectos."]], "e": "Se resumen en \"qué probar\" (caso), \"cómo probar\" (procedimiento) y \"cómo automatizarlo\" (componente).", "inf": true, "ref": "apunte, págs. 120-122."},
  {"id": "ia-06-18", "unit": "b3", "t": "multi", "tema": "Prueba", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-18 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre las pruebas de integración y de sistema.", "o": ["Las pruebas de integración son necesarias para cada construcción dentro de la iteración.", "Las pruebas de sistema son necesarias solo al final de la iteración.", "La prueba de sistema debe iniciarse antes de cualquier prueba de integración.", "Los casos de prueba de integración toman como entrada los diagramas de interacción de las realizaciones de caso de uso.", "Algunos casos de prueba de construcciones anteriores nunca pueden usarse como pruebas de regresión."], "a": [0, 1, 3], "e": "«Las pruebas de integración son necesarias para cada…» / «Las pruebas de sistema son necesarias solo al final de la…»: lo dice el apunte.\n«La prueba de sistema debe iniciarse antes de cualquier…»: puede empezar cuando las pruebas de integración indican que se cumplen los objetivos de calidad.\n«Los casos de prueba de integración toman como entrada los…»: se comparan las interacciones reales con ese diagrama.\n«Algunos casos de prueba de construcciones anteriores nunca…»: es lo contrario: pueden usarse para regresión, aunque con esfuerzo extra.", "inf": true, "ref": "apunte, págs. 118-119 y 123-126."},
  {"id": "ia-06-19", "unit": "b3", "t": "multi", "tema": "Prueba", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 06-19 · pregunta generada con IA", "q": "Sobre la prueba de unidad y la evaluación de la prueba, marque las afirmaciones correctas.", "o": ["La prueba de estructura (caja blanca) ignora la implementación interna de la unidad.", "Usar clases de equivalencia permite obtener una cobertura casi igual con considerablemente menos esfuerzo.", "La prueba de especificación (caja negra) verifica el comportamiento observable externamente de la unidad.", "Las métricas de la evaluación son la compleción de la prueba y la fiabilidad.", "La fiabilidad indica solo el porcentaje de código probado."], "a": [1, 2, 3], "e": "«La prueba de estructura (caja blanca) ignora la…»: es al revés: verifica la implementación interna.\n«Usar clases de equivalencia permite obtener una cobertura…»: lo dice el apunte.\n«La prueba de especificación (caja negra) verifica el…»: es la definición del apunte.\n«Las métricas de la evaluación son la compleción de la…»: son las dos métricas.\n«La fiabilidad indica solo el porcentaje de código probado.»: eso pertenece a la compleción. La fiabilidad analiza tendencias en defectos y pruebas.", "inf": true, "ref": "apunte, págs. 118 y 126-127."},
  {"id": "ia-07-12", "unit": "b4", "t": "multi", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-12 · pregunta generada con IA", "q": "Según GoF, ¿cuáles de los siguientes son los cuatro elementos fundamentales de un patrón? Seleccione todas las correctas.", "o": ["Solución", "Fuerzas", "Contexto resultante", "Problema", "Nombre", "Consecuencias"], "a": [0, 3, 4, 5], "e": "«Solución» / «Problema» / «Nombre» / «Consecuencias»: son los cuatro elementos que enumera el apunte. Las consecuencias son los resultados y las compensaciones de aplicar el patrón.\n«Fuerzas» / «Contexto resultante»: pertenecen a la forma de Alexander.", "inf": true, "ref": "apunte, págs. 128 y 130."},
  {"id": "ia-07-13", "unit": "b4", "t": "multi", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-13 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre los patrones de diseño.", "o": ["Proveen una solución exacta y resuelven todos los problemas de diseño.", "Permiten tener un vocabulario común con el equipo de desarrollo.", "Un lenguaje de patrones incluye reglas y guías para combinar patrones y resolver un problema mayor.", "La solución no describe una implementación concreta: es como una plantilla aplicable a muchas situaciones.", "Un patrón solo puede aplicarse en programación orientada a objetos y nunca va más allá."], "a": [1, 2, 3], "e": "«Proveen una solución exacta y resuelven todos los problemas…»: el apunte dice que no proveen una solución exacta.\n«Permiten tener un vocabulario común con el equipo de…»: es una de las propiedades que lista el apunte.\n«Un lenguaje de patrones incluye reglas y guías para…»: es la definición de lenguaje de patrones.\n«La solución no describe una implementación concreta: es…»: lo dice el apunte de forma explícita.\n«Un patrón solo puede aplicarse en programación orientada a…»: el apunte dice que van más allá del diseño orientado a objetos.", "inf": true, "ref": "apunte, págs. 127-128 y 131."},
  {"id": "ia-07-14", "unit": "b4", "t": "rel", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-14 · pregunta generada con IA", "q": "Empareje cada patrón con su propósito según el catálogo de GoF.", "i": [["Builder", "Creacional"], ["Prototype", "Creacional"], ["Bridge", "Estructural"], ["Decorator", "Estructural"], ["Flyweight", "Estructural"], ["Mediator", "Comportamiento"], ["Visitor", "Comportamiento"]], "e": "Los creacionales abstraen la instanciación. Los estructurales componen clases u objetos. Los de comportamiento caracterizan cómo interactúan y se distribuyen responsabilidades.", "inf": true, "nota": "la tabla del apunte (pág. 132) ubica a Flyweight en la columna \"Comportamental\". El catálogo de GoF, según NotebookLM, lo clasifica como estructural. Acá se usa la clasificación de GoF.", "ref": "apunte, págs. 131-132; Gamma et al."},
  {"id": "ia-07-15", "unit": "b4", "t": "multi", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-15 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre el alcance de los patrones son correctas? Seleccione todas las correctas.", "o": ["Factory Method, Interpreter y Template Method son patrones de alcance de clase.", "Los patrones de clase cambian sus relaciones libremente en tiempo de ejecución.", "La mayoría de los patrones pertenecen al alcance de objeto.", "Los patrones de clase tratan relaciones establecidas por herencia, fijas en tiempo de compilación.", "Los patrones de objeto no utilizan nunca la herencia."], "a": [0, 2, 3], "e": "«Factory Method, Interpreter y Template Method son patrones…»: también Adapter en su variante de clase.\n«Los patrones de clase cambian sus relaciones libremente en…»: eso caracteriza a los patrones de objeto.\n«La mayoría de los patrones pertenecen al alcance de objeto.»: lo dice el apunte de forma explícita.\n«Los patrones de clase tratan relaciones establecidas por…»: por eso son estáticos.\n«Los patrones de objeto no utilizan nunca la herencia.»: casi todos los patrones usan herencia hasta cierto punto.", "inf": true, "ref": "apunte, págs. 131-132."},
  {"id": "ia-07-16", "unit": "b4", "t": "multi", "tema": "Factory Method", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-16 · pregunta generada con IA", "q": "Una aplicación de logística define la clase abstracta Logistica, con la operación crearTransporte(), y las subclases LogisticaTerrestre y LogisticaMaritima, que crean Camion y Barco. Ambos implementan Transporte. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["El código de Logistica depende de la abstracción Transporte y no de las clases concretas.", "Transporte es el Product, y Camion, un ConcreteProduct.", "El patrón obliga a crear los objetos directamente con new en el código cliente.", "Es un Abstract Factory, porque crea una familia de productos relacionados.", "Logistica cumple el rol de Creator, y LogisticaTerrestre, el de ConcreteCreator."], "a": [0, 1, 4], "e": "«El código de Logistica depende de la abstracción Transporte…»: es la ventaja que señala el apunte.\n«Transporte es el Product, y Camion, un ConcreteProduct.» / «Logistica cumple el rol de Creator, y LogisticaTerrestre,…»: son los participantes que define el apunte.\n«El patrón obliga a crear los objetos directamente con new…»: delega la creación a las subclases, en lugar de usar new directamente.\n«Es un Abstract Factory, porque crea una familia de…»: hay un solo tipo de producto, no una familia.", "inf": true, "ref": "apunte, págs. 133-134."},
  {"id": "ia-07-17", "unit": "b4", "t": "multi", "tema": "Singleton", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-17 · pregunta generada con IA", "q": "Analice el siguiente código y marque las afirmaciones correctas.", "code": "public class Configuracion {\n    private static Configuracion instancia;\n\n    private Configuracion() { }\n\n    public static Configuracion getInstancia() {\n        if (instancia == null) {\n            instancia = new Configuracion();\n        }\n        return instancia;\n    }\n}", "o": ["Aplica Singleton: garantiza una sola instancia y un punto de acceso global.", "getInstancia() es una operación de clase.", "El constructor debería ser público, para que los clientes creen las instancias que necesiten.", "La clase es responsable de crear y mantener su propia instancia única.", "Es un patrón creacional de alcance de clase."], "a": [0, 1, 3], "e": "«Aplica Singleton: garantiza una sola instancia y un punto…»: es la intención del patrón.\n«getInstancia() es una operación de clase.»: el apunte aclara que \"instancia es una operación de clase\".\n«El constructor debería ser público, para que los clientes…»: un constructor público permitiría crear más instancias.\n«La clase es responsable de crear y mantener su propia…»: es la responsabilidad del participante Singleton.\n«Es un patrón creacional de alcance de clase.»: es creacional, pero de alcance de objeto.", "inf": true, "ref": "apunte, págs. 132 y 134-135."},
  {"id": "ia-07-18", "unit": "b4", "t": "rel", "tema": "Facade, Proxy, State e Iterator", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-18 · pregunta generada con IA", "q": "Empareje cada situación con el tipo de Proxy que corresponde.", "i": [["Proxy remoto", "El objeto real está en otro espacio de direcciones, y hay que codificar y enviar la solicitud."], ["Proxy virtual", "Una imagen pesada solo se carga cuando realmente hace falta mostrarla."], ["Proxy de protección", "Se debe verificar que quien llama tenga permisos para ejecutar la solicitud."]], "e": "En los tres casos el proxy ofrece la misma interfaz que Subject, de modo que puede sustituir al sujeto real.", "inf": true, "ref": "apunte, págs. 140-141."},
  {"id": "ia-07-19", "unit": "b4", "t": "multi", "tema": "Observer", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-19 · pregunta generada con IA", "q": "Una planilla muestra los mismos datos en una tabla y en dos gráficos. Cuando un dato cambia, todas las vistas deben actualizarse, y deben poder agregarse vistas nuevas sin tocar la planilla. Si se aplica Observer, ¿qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Cada vista debe consultar permanentemente si hubo cambios, porque el Subject no notifica.", "Se define una dependencia de uno a muchos entre objetos.", "Los datos de la planilla cumplen el rol de ConcreteSubject, y las vistas, el de ConcreteObserver.", "El Subject proporciona una interfaz para adjuntar y separar observadores.", "El Subject debe conocer la clase concreta de cada vista para poder notificarla."], "a": [1, 2, 3], "e": "«Cada vista debe consultar permanentemente si hubo cambios,…»: el ConcreteSubject envía una notificación cuando su estado cambia.\n«Se define una dependencia de uno a muchos entre objetos.»: es la intención del patrón.\n«Los datos de la planilla cumplen el rol de ConcreteSubject,…»: el ConcreteSubject guarda el estado de interés.\n«El Subject proporciona una interfaz para adjuntar y separar…»: es parte de la responsabilidad del Subject.\n«El Subject debe conocer la clase concreta de cada vista…»: justamente se busca notificar sin hacer suposiciones sobre quiénes son.", "inf": true, "ref": "apunte, págs. 143-144."},
  {"id": "ia-07-20", "unit": "b4", "t": "multi", "tema": "Facade, Proxy, State e Iterator", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-20 · pregunta generada con IA", "q": "¿En qué situaciones resulta apropiado aplicar Iterator? Seleccione todas las correctas.", "o": ["Para notificar a otros objetos cuando cambia el estado del contenedor.", "Para acceder al contenido de un contenedor sin exponer su representación interna.", "Para ofrecer una interfaz uniforme que recorra distintos tipos de contenedores.", "Para permitir varios recorridos simultáneos sobre un contenedor.", "Para garantizar que un contenedor tenga una única instancia global."], "a": [1, 2, 3], "e": "«Para notificar a otros objetos cuando cambia el estado del…»: eso es Observer.\n«Para acceder al contenido de un contenedor sin exponer su…» / «Para ofrecer una interfaz uniforme que recorra distintos…» / «Para permitir varios recorridos simultáneos sobre un…»: son las tres situaciones de aplicabilidad del apunte. La última se conoce como iteración polimórfica.\n«Para garantizar que un contenedor tenga una única instancia…»: eso es Singleton.", "inf": true, "ref": "apunte, pág. 144."},
  {"id": "ia-07-21", "unit": "b4", "t": "rel", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-21 · pregunta generada con IA", "q": "Empareje cada participante con el patrón al que pertenece.", "i": [["Adaptee", "Adapter"], ["Leaf", "Composite"], ["Subsystem classes", "Facade"], ["RealSubject", "Proxy"], ["ConcreteState", "State"], ["ConcreteAggregate", "Iterator"]], "e": "Adaptee es la interfaz existente que necesita adaptación. Leaf no tiene hijos. Las clases del subsistema no tienen conocimiento de la fachada. RealSubject es el objeto real que el proxy representa. Cada ConcreteState implementa un comportamiento asociado a un estado. ConcreteAggregate devuelve el iterador adecuado.", "inf": true, "ref": "apunte, págs. 137-145."},
  {"id": "ia-07-22", "unit": "b4", "t": "rel", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-22 · pregunta generada con IA", "q": "Empareje cada situación con el patrón creacional más adecuado. El apunte solo nombra Builder y Prototype en el catálogo.", "i": [["Builder", "El mismo proceso de construcción paso a paso debe poder crear distintas representaciones de un objeto complejo."], ["Prototype", "Los objetos nuevos se crean copiando una instancia existente."], ["Abstract Factory", "Hay que crear familias de objetos relacionados sin especificar sus clases concretas."], ["Factory Method", "Una clase quiere que sus subclases decidan qué objeto crear."], ["Singleton", "Debe existir una única instancia, accesible desde un punto conocido."]], "e": "Todos encapsulan el conocimiento de qué clases concretas se usan y ocultan cómo se crean y ensamblan sus instancias.", "inf": true, "ref": "apunte, págs. 133-135; Gamma et al., pp. 97 (Builder) y 117 (Prototype)."},
  {"id": "ia-07-23", "unit": "b4", "t": "multi", "tema": "Otros patrones del catálogo", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-23 · pregunta generada con IA", "q": "Un sistema guarda datos en archivos, y a veces debe además comprimirlos o cifrarlos, en cualquier combinación. Crear una subclase por cada combinación generaría una explosión de clases. El apunte solo nombra Decorator en el catálogo. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Es un patrón creacional, porque crea nuevas variantes de la clase.", "Es una alternativa flexible a la subclasificación para extender funcionalidad.", "Las responsabilidades agregadas pueden combinarse y también retirarse.", "Afecta a todos los objetos de la clase, porque modifica la clase original.", "Decorator permite añadir responsabilidades a un objeto de forma dinámica."], "a": [1, 2, 4], "e": "«Es un patrón creacional, porque crea nuevas variantes de la…»: es estructural.\n«Es una alternativa flexible a la subclasificación para…» / «Decorator permite añadir responsabilidades a un objeto de…»: es la intención que da GoF.\n«Las responsabilidades agregadas pueden combinarse y también…»: es uno de los casos de aplicación.\n«Afecta a todos los objetos de la clase, porque modifica la…»: se aplica a objetos individuales, sin afectar a otros.", "inf": true, "ref": "Gamma et al., p. 175. El apunte solo lo nombra."},
  {"id": "ia-07-24", "unit": "b4", "t": "multi", "tema": "Otros patrones del catálogo", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-24 · pregunta generada con IA", "q": "Un sistema tiene controles remotos (Remote, AdvancedRemote) que deben funcionar con distintos dispositivos (Radio, TV). Ambas jerarquías deben poder crecer por separado. El apunte solo nombra Bridge en el catálogo. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Evita un enlace permanente entre abstracción e implementación, que incluso puede seleccionarse en tiempo de ejecución.", "Es lo mismo que Adapter: su propósito es hacer compatibles interfaces ya existentes.", "Combina las dos jerarquías en una sola, con una subclase por cada combinación.", "Bridge desacopla una abstracción de su implementación para que ambas varíen independientemente."], "a": [0, 3], "e": "«Evita un enlace permanente entre abstracción e…»: es uno de los casos de aplicación.\n«Es lo mismo que Adapter: su propósito es hacer compatibles…»: adapter compatibiliza interfaces existentes; Bridge separa dos dimensiones de variación (Gamma et al., según NotebookLM).\n«Combina las dos jerarquías en una sola, con una subclase…»: es el problema que Bridge evita.\n«Bridge desacopla una abstracción de su implementación para…»: es la intención de GoF.", "inf": true, "ref": "Gamma et al., p. 151. El apunte solo lo nombra."},
  {"id": "ia-07-25", "unit": "b4", "t": "multi", "tema": "Otros patrones del catálogo", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-25 · pregunta generada con IA", "q": "Un procesador de texto debe manejar millones de caracteres, y crear un objeto completo por cada uno consume demasiada memoria. El apunte solo nombra Flyweight en el catálogo. ¿Qué afirmaciones son correctas? Seleccione todas las correctas.", "o": ["Puede tener un costo en tiempo de cómputo para transferir o calcular el estado extrínseco.", "Flyweight usa el compartimiento para soportar eficientemente un gran número de objetos de grano fino.", "Exige que cada objeto tenga una copia de todo su estado.", "Es aplicable cuando la mayor parte del estado de los objetos no puede hacerse extrínseco.", "Se comparte el estado intrínseco, y el extrínseco se transfiere o calcula."], "a": [0, 1, 4], "e": "«Puede tener un costo en tiempo de cómputo para transferir o…»: es la compensación del patrón.\n«Flyweight usa el compartimiento para soportar…»: es la intención de GoF.\n«Exige que cada objeto tenga una copia de todo su estado.»: es lo contrario de compartir.\n«Es aplicable cuando la mayor parte del estado de los…»: es aplicable cuando la mayor parte del estado sí puede hacerse extrínseco.\n«Se comparte el estado intrínseco, y el extrínseco se…»: es lo que reduce el consumo de memoria.", "inf": true, "ref": "Gamma et al., p. 195. El apunte solo lo nombra."},
  {"id": "ia-07-26", "unit": "b4", "t": "rel", "tema": "GoF: definición, formato y clasificación", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-26 · pregunta generada con IA", "q": "Empareje cada patrón con su intención. El apunte solo nombra estos patrones en el catálogo.", "i": [["Command", "Encapsular una petición como un objeto, para encolarla, registrarla o deshacerla."], ["Chain of Responsibility", "Pasar una petición a lo largo de una cadena de objetos hasta que alguno la maneje."], ["Mediator", "Encapsular cómo interactúa un conjunto de objetos, evitando que se refieran entre sí."], ["Memento", "Capturar y externalizar el estado interno de un objeto, sin violar la encapsulación, para restaurarlo después."], ["Visitor", "Definir una nueva operación sin cambiar las clases de los elementos sobre los que opera."]], "e": "Son las intenciones de GoF. Son útiles también para reconocer las figuras del bloque 09.", "inf": true, "ref": "Gamma et al., pp. 223, 233, 273, 283 y 331. El apunte solo los nombra (Chain of Responsibility aparece en la tabla como \"Responsability\")."},
  {"id": "ia-07-27", "unit": "b4", "t": "multi", "tema": "Strategy", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 07-27 · pregunta generada con IA", "q": "Se quiere exportar reportes en varios formatos. Todos siguen los mismos pasos (abrir, escribir, cerrar), y solo cambia cómo se escribe. ¿Qué afirmaciones sobre Template Method y Strategy son correctas? Seleccione todas las correctas.", "o": ["Strategy encapsula una familia de algoritmos intercambiables y es de alcance de objeto.", "Con Template Method, las subclases deben reescribir la estructura completa del algoritmo.", "Template Method es de alcance de clase, porque se basa en la herencia.", "Template Method define el esqueleto del algoritmo y delega algunos pasos a las subclases.", "Strategy obliga a usar herencia para cambiar el algoritmo en tiempo de compilación."], "a": [0, 2, 3], "e": "«Strategy encapsula una familia de algoritmos…»: es la intención de GoF.\n«Con Template Method, las subclases deben reescribir la…»: redefinen ciertos pasos sin cambiar la estructura.\n«Template Method es de alcance de clase, porque se basa en…»: el apunte lo ubica en el alcance de clase.\n«Template Method define el esqueleto del algoritmo y delega…»: es la intención de GoF.\n«Strategy obliga a usar herencia para cambiar el algoritmo…»: strategy usa composición y permite variar el algoritmo independientemente del cliente.", "inf": true, "ref": "apunte, págs. 132 y 141-142; Gamma et al., pp. 315 y 325."},
  {"id": "ia-08-03", "unit": "b5", "t": "multi", "tema": "Agilidad y Manifiesto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-03 · pregunta generada con IA", "q": "Según el apunte, ¿cuáles de las siguientes son diferencias entre las metodologías ágiles y las clásicas? Seleccione todas las correctas.", "o": ["Las ágiles son adaptativas en vez de predictivas.", "Las ágiles son menos orientadas a la documentación y más orientadas al código.", "Las ágiles eliminan todo proceso y buscan la ausencia total de formalidad.", "Las ágiles están más orientadas a las personas que a los procesos.", "Las clásicas consideran a las personas como el factor más importante y no como recursos reemplazables."], "a": [0, 1, 3], "e": "«Las ágiles son adaptativas en vez de predictivas.» / «Las ágiles son menos orientadas a la documentación y más…» / «Las ágiles están más orientadas a las personas que a los…»: son las diferencias que enumera el apunte.\n«Las ágiles eliminan todo proceso y buscan la ausencia total…»: buscan una solución de compromiso entre la ausencia de procesos y el exceso de burocracia.\n«Las clásicas consideran a las personas como el factor más…»: es al revés: las tradicionales tratan a las personas como recursos con distintos roles.", "inf": true, "ref": "apunte, págs. 145-146."},
  {"id": "ia-08-04", "unit": "b5", "t": "rel", "tema": "Agilidad y Manifiesto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-04 · pregunta generada con IA", "q": "Empareje cada elemento valorado por el Manifiesto Ágil con aquello por sobre lo cual se lo valora.", "i": [["Individuos e interacciones", "Procesos y herramientas"], ["Software funcionando", "Extensa documentación"], ["Colaboración del cliente", "Negociación contractual"], ["Responder al cambio", "Seguir un plan"]], "e": "Son los cuatro valores acordados en febrero de 2001.", "inf": true, "ref": "apunte, pág. 146."},
  {"id": "ia-08-05", "unit": "b5", "t": "multi", "tema": "Agilidad y Manifiesto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-05 · pregunta generada con IA", "q": "¿Cuáles de los siguientes son principios del Manifiesto Ágil? Seleccione todas las correctas.", "o": ["Toda decisión debe documentarse de forma exhaustiva antes de codificar.", "La simplicidad, el arte de maximizar el trabajo no realizado, es esencial.", "El método más eficiente para transmitir información es la conversación cara a cara.", "Software funcionando es la primera medida de progreso.", "La primera medida de progreso es el cumplimiento del plan inicial.", "El cambio de requerimientos es bienvenido, aún tarde en el desarrollo."], "a": [1, 2, 3, 5], "e": "«Toda decisión debe documentarse de forma exhaustiva antes…»: contradice el valor \"software funcionando por sobre extensa documentación\".\n«La simplicidad, el arte de maximizar el trabajo no…» / «El método más eficiente para transmitir información es la…» / «Software funcionando es la primera medida de progreso.» / «El cambio de requerimientos es bienvenido, aún tarde en el…»: son los principios 2, 7, 10 y 6.\n«La primera medida de progreso es el cumplimiento del plan…»: contradice el principio 7.", "inf": true, "ref": "apunte, págs. 146-147."},
  {"id": "ia-08-06", "unit": "b5", "t": "rel", "tema": "Agilidad y Manifiesto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-06 · pregunta generada con IA", "q": "Empareje cada framework ágil con la característica que lo identifica.", "i": [["DSDM", "Priorización MoSCoW y timeboxes."], ["Scrum", "Sprints de 1 a 4 semanas, con Product Owner, Scrum Master y Equipo."], ["FDD", "Desarrollo a partir de pequeñas funcionalidades que aportan valor, con un enfoque más estructurado."], ["Crystal", "Familia de metodologías identificada por colores, según el tamaño del equipo y la criticidad."], ["ASD", "Ciclo de Speculate, Collaborate y Learn."]], "e": "El apunte aclara que todos se alinean con los valores del Manifiesto y comparten la idea de que los procesos deben ajustarse al equipo.", "inf": true, "ref": "apunte, págs. 147-149."},
  {"id": "ia-08-07", "unit": "b5", "t": "multi", "tema": "Agilidad y Manifiesto", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-07 · pregunta generada con IA", "q": "Sobre Scrum, marque las afirmaciones correctas.", "o": ["Utiliza artefactos como el Product Backlog, el Sprint Backlog y el incremento de producto.", "Sus ceremonias incluyen Daily, Review, Planning y Retrospective.", "Fue el último framework en surgir, después del Manifiesto Ágil.", "Sus ciclos de trabajo duran típicamente entre 6 y 12 meses.", "Sus roles son Product Owner, Scrum Master y Equipo."], "a": [0, 1, 4], "e": "«Utiliza artefactos como el Product Backlog, el Sprint…» / «Sus ceremonias incluyen Daily, Review, Planning y…» / «Sus roles son Product Owner, Scrum Master y Equipo.»: lo enumera el apunte.\n«Fue el último framework en surgir, después del Manifiesto…»: es de 1995, y el Manifiesto es de 2001.\n«Sus ciclos de trabajo duran típicamente entre 6 y 12 meses.»: los sprints duran típicamente de 1 a 4 semanas.", "inf": true, "ref": "apunte, pág. 148."},
  {"id": "ia-08-08", "unit": "b5", "t": "mc", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-08 · pregunta generada con IA", "q": "Una empresa evalúa adoptar XP. ¿En cuál de los siguientes contextos resulta más adecuado, según el apunte?", "o": ["Un sistema con hardware específico, desarrollado exclusivamente por especialistas en hardware.", "Un equipo de 200 personas distribuido, con requisitos estables y documentación exhaustiva.", "Un equipo de 6 personas, en un dominio muy dinámico, con cambios de requerimientos altos y rápidos.", "Un proyecto con plan de calidad formal y revisión estructurada, sin participación del cliente."], "a": 2, "e": "«Un sistema con hardware específico, desarrollado…»: XP se dirige explícitamente al desarrollo de software. El hardware específico es una limitación.\n«Un equipo de 200 personas distribuido, con requisitos…»: con equipos más grandes es de difícil aplicación.\n«Un equipo de 6 personas, en un dominio muy dinámico, con…»: XP fue creada para dominios muy dinámicos y está orientada a equipos de 2 a 10 personas.\n«Un proyecto con plan de calidad formal y revisión…»: XP requiere un equipo extendido, que incluye a los clientes.", "inf": true, "ref": "apunte, págs. 149-150 y 157."},
  {"id": "ia-08-09", "unit": "b5", "t": "rel", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-09 · pregunta generada con IA", "q": "Empareje cada valor de XP con su descripción.", "i": [["Simplicidad", "Elegir la solución más simple y no trabajar sobre problemas inexistentes."], ["Comunicación", "Hablar cara a cara y en un lugar físico."], ["Retroalimentación", "El software funcionando marca si se está avanzando o no."], ["Coraje", "No tener miedo de comunicar que algo va mal, incluso al cliente."], ["Respeto", "Nadie del equipo debería tener miedo a expresar su opinión."]], "e": "El apunte asocia el respeto con la \"seguridad psicológica\".", "inf": true, "ref": "apunte, págs. 149-150."},
  {"id": "ia-08-10", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-10 · pregunta generada con IA", "q": "Sobre los principios de XP, marque las afirmaciones correctas.", "o": ["Viaje liviano significa mantener solo los artefactos mínimos e indispensables.", "Retroalimentación rápida, suponer simplicidad y abrazar el cambio son principios centrales.", "Adaptación local significa aplicar XP exactamente igual en todos los proyectos.", "Pequeña inversión inicial sostiene que un presupuesto acotado al principio ayuda a enfocarse.", "Cambio incremental propone integrar los cambios una sola vez, al final del proyecto."], "a": [0, 1, 3], "e": "«Viaje liviano significa mantener solo los artefactos…»: para muchos proyectos, el código es la documentación.\n«Retroalimentación rápida, suponer simplicidad y abrazar el…»: son principios centrales.\n«Adaptación local significa aplicar XP exactamente igual en…»: \"cambia para cada proyecto\".\n«Pequeña inversión inicial sostiene que un presupuesto…»: lo explica el apunte.\n«Cambio incremental propone integrar los cambios una sola…»: el apunte indica entregas de unas 2 semanas, con un máximo de 4.", "inf": true, "ref": "apunte, págs. 150-151."},
  {"id": "ia-08-11", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-11 · pregunta generada con IA", "q": "¿Cuáles de las siguientes afirmaciones sobre las actividades básicas y las prácticas de XP son correctas? Seleccione todas las correctas.", "o": ["Diseñar es la actividad principal de XP, y se hace antes de programar.", "La semana de 40 horas, el cliente en el sitio y la propiedad colectiva son prácticas de XP.", "La programación a pares es una práctica característica de XP.", "Las actividades básicas son programar, probar, escuchar y diseñar.", "La integración de los cambios se hace únicamente al final de cada entrega."], "a": [1, 2, 3], "e": "«Diseñar es la actividad principal de XP, y se hace antes de…»: en el diseño se hace muy poco foco, y es para mejorar lo que ya está hecho.\n«La semana de 40 horas, el cliente en el sitio y la…»: figuran entre las prácticas centrales.\n«La programación a pares es una práctica característica de…»: el apunte la señala como característica.\n«Las actividades básicas son programar, probar, escuchar y…»: programar es la actividad principal.\n«La integración de los cambios se hace únicamente al final…»: la integración continua es una práctica central.", "inf": true, "ref": "apunte, págs. 151-152."},
  {"id": "ia-08-12", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-12 · pregunta generada con IA", "q": "Marque las afirmaciones correctas sobre la metáfora y el diseño simple en XP.", "o": ["La metáfora explica cómo funciona el sistema sin usar términos técnicos.", "La metáfora es la práctica más utilizada en sistemas muy grandes.", "El diseño simple busca la mayor cantidad posible de clases y métodos.", "El diseño correcto ejecuta todas las pruebas y no tiene lógica duplicada.", "El diseño simple se opone al consejo \"implemente para hoy, diseñe para mañana\"."], "a": [0, 3, 4], "e": "«La metáfora explica cómo funciona el sistema sin usar…»: es la definición del apunte.\n«La metáfora es la práctica más utilizada en sistemas muy…»: es la menos utilizada, porque en sistemas muy grandes se vuelve complicada.\n«El diseño simple busca la mayor cantidad posible de clases…»: busca la menor cantidad posible.\n«El diseño correcto ejecuta todas las pruebas y no tiene…»: además, declara las intenciones importantes de los programadores.\n«El diseño simple se opone al consejo \"implemente para hoy,…»: se diseña para lo que se necesita hoy.", "inf": true, "ref": "apunte, pág. 152."},
  {"id": "ia-08-13", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-13 · pregunta generada con IA", "q": "Un cliente escribe \"Como cajero quiero anular una venta\" en una tarjeta. ¿Qué afirmaciones sobre historias de usuario y pruebas de aceptación en XP son correctas? Seleccione todas las correctas.", "o": ["Las pruebas de aceptación se derivan de las historias y son pruebas de caja negra.", "Una historia no está completa hasta que pasa sus pruebas de aceptación.", "Los desarrolladores escriben las historias con detalle técnico y las verifican sin intervención del cliente.", "Las historias las escribe el cliente, sin lenguaje técnico y con el detalle mínimo para estimarlas.", "Cada historia debe tener exactamente una prueba de aceptación."], "a": [0, 1, 3], "e": "«Las pruebas de aceptación se derivan de las historias y son…»: lo dice el apunte.\n«Una historia no está completa hasta que pasa sus pruebas de…»: lo dice el apunte.\n«Los desarrolladores escriben las historias con detalle…»: las escribe el cliente, y él verifica la ejecución de las pruebas.\n«Las historias las escribe el cliente, sin lenguaje técnico…»: lo dice el apunte.\n«Cada historia debe tener exactamente una prueba de…»: puede tener una o varias.", "inf": true, "ref": "apunte, págs. 153-156."},
  {"id": "ia-08-14", "unit": "b5", "t": "rel", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-14 · pregunta generada con IA", "q": "Empareje cada variable de la planificación de entregas de XP con su significado.", "i": [["Alcance", "Cuánto trabajo deberá realizarse."], ["Recursos", "Cuántas personas están disponibles."], ["Tiempo", "Cuándo se realizará el proyecto o la entrega."], ["Calidad", "Cuán bueno será el sistema y cuán bien probado estará."]], "e": "En la planificación se estiman las historias y el cliente define la prioridad. Una iteración dura de 1 a 3 semanas, con tareas cortas de 1 a 3 días.", "inf": true, "ref": "apunte, pág. 155."},
  {"id": "ia-08-15", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-15 · pregunta generada con IA", "q": "Un equipo no logra estimar una historia porque depende de una tecnología que nunca usó. ¿Qué afirmaciones son correctas según las reglas de diseño de XP? Seleccione todas las correctas.", "o": ["Puede diseñar colaborativamente usando tarjetas CRC.", "Debe detener el proyecto hasta tener un diseño formal completo del sistema.", "Puede crear una solución spike, muy sencilla, para experimentar y tener una estimación más confiable.", "No debe desarrollar nada anticipado: solo lo necesario en la iteración actual.", "El código del spike debe incorporarse siempre al sistema final tal como está."], "a": [0, 2, 3], "e": "«Puede diseñar colaborativamente usando tarjetas CRC.»: es una de las reglas de diseño.\n«Debe detener el proyecto hasta tener un diseño formal…»: XP no se basa en un diseño formal previo.\n«Puede crear una solución spike, muy sencilla, para…»: reduce el riesgo técnico: \"incertidumbre → spike → estimación confiable\".\n«No debe desarrollar nada anticipado: solo lo necesario en…»: es una de las reglas de diseño.\n«El código del spike debe incorporarse siempre al sistema…»: el spike no busca hacer el sistema final, sino aprender.", "inf": true, "ref": "apunte, págs. 154-157."},
  {"id": "ia-08-16", "unit": "b5", "t": "multi", "tema": "XP", "src": "Simulacro DSI (preguntas viejas y nuevas).html · ítem 08-16 · pregunta generada con IA", "q": "¿Cuáles de las siguientes son limitaciones de XP señaladas en el apunte? Seleccione todas las correctas.", "o": ["No admite cambios de requerimientos durante el proyecto.", "Demanda personas sobresalientes, de múltiples capacidades.", "Falta un proceso de revisión estructurado y un plan de calidad.", "La falta de diseño formal puede ser peligrosa para grandes sistemas.", "Exige demasiada documentación formal antes de codificar.", "Pérdida de documentación, limitada al código."], "a": [1, 2, 3, 5], "e": "«No admite cambios de requerimientos durante el proyecto.»: XP abraza el cambio.\n«Demanda personas sobresalientes, de múltiples capacidades.» / «Falta un proceso de revisión estructurado y un plan de…» / «La falta de diseño formal puede ser peligrosa para grandes…» / «Pérdida de documentación, limitada al código.»: figuran en la lista del apunte.\n«Exige demasiada documentación formal antes de codificar.»: es lo contrario: la documentación se limita al código.", "inf": true, "ref": "apunte, pág. 157."},
]
